  function mapGeneration(map, key) {
    return clampInt(map.get(String(key || '')) || 0, 0, 0, 1000000000);
  }

  function captureBackgroundFence(scope = null) {
    const sourceBundleKey = String(scope?.sourceBundleKey || '');
    const scopeKey = String(scope?.scopeKey || '');
    return {
      lifecycleEpoch,
      transferGeneration,
      resetGeneration,
      allResetGeneration,
      sourceBundleKey,
      scopeKey,
      botResetGeneration: mapGeneration(botResetGenerations, sourceBundleKey),
      scopeResetGeneration: mapGeneration(scopeResetGenerations, scopeKey),
    };
  }

  function backgroundFenceIsCurrent(token) {
    if (!token || unloaded || stateRecoveryFault) return false;
    return !backgroundFenceResetInvalidated(token)
      && (token.transferGeneration === undefined || token.transferGeneration === transferGeneration)
      && (token.enforceLifecycleEpoch !== true || token.lifecycleEpoch === lifecycleEpoch)
      && (token.moduleSelectionGeneration === undefined || token.moduleSelectionGeneration === mapGeneration(moduleSelectionGenerations, token.sourceBundleKey))
      && (token.loreSelectionGeneration === undefined || token.loreSelectionGeneration === mapGeneration(loreSelectionGenerations, token.sourceBundleKey))
      && (token.profileAuditGeneration === undefined || token.profileAuditGeneration === profileAuditGeneration)
      && (token.autoProfileRefreshGeneration === undefined || token.autoProfileRefreshGeneration === autoProfileRefreshGeneration);
  }

  function backgroundFenceResetInvalidated(token) {
    if (!token) return true;
    return token.allResetGeneration !== allResetGeneration
      || token.botResetGeneration !== mapGeneration(botResetGenerations, token.sourceBundleKey)
      || token.scopeResetGeneration !== mapGeneration(scopeResetGenerations, token.scopeKey);
  }

  function staleLifecycleError(stage = 'background task') {
    const error = new Error(`stale ${stage} discarded after reset or unload`);
    error.code = 'EROSYNC_STALE_LIFECYCLE';
    return error;
  }

  function assertBackgroundFence(token, stage = 'background task') {
    if (backgroundFenceIsCurrent(token)) return;
    throw staleLifecycleError(stage);
  }

  function isStaleLifecycleError(error) {
    return String(error?.code || '').startsWith('EROSYNC_STALE_')
      || error?.code === 'EROSYNC_RISU_PREEMPTED';
  }

  function captureBehindFence(scope) {
    const sourceBundleKey = String(scope?.sourceBundleKey || '');
    const scopeKey = String(scope?.scopeKey || '');
    return {
      ...captureBackgroundFence(scope),
      behindAllGeneration,
      behindBotGeneration: mapGeneration(behindBotGenerations, sourceBundleKey),
      behindScopeGeneration: mapGeneration(behindScopeGenerations, scopeKey),
    };
  }

  function behindFenceIsCurrent(token) {
    return backgroundFenceIsCurrent(token)
      && token.behindAllGeneration === behindAllGeneration
      && token.behindBotGeneration === mapGeneration(behindBotGenerations, token.sourceBundleKey)
      && token.behindScopeGeneration === mapGeneration(behindScopeGenerations, token.scopeKey);
  }

  function assertBehindFence(token, stage = 'Behind task') {
    if (behindFenceIsCurrent(token)) return;
    throw staleLifecycleError(stage);
  }

  function bumpBehindGeneration(scopeMode = 'all', botKey = '', scopeKey = '') {
    if (scopeMode === 'chat' && scopeKey) behindScopeGenerations.set(scopeKey, mapGeneration(behindScopeGenerations, scopeKey) + 1);
    else if (scopeMode === 'bot' && botKey) behindBotGenerations.set(botKey, mapGeneration(behindBotGenerations, botKey) + 1);
    else behindAllGeneration += 1;
  }

  function enqueueSharedProfileRegistryWrite(task) {
    const run = sharedProfileRegistryWriteQueue.then(task, task);
    sharedProfileRegistryWriteQueue = run.catch(() => {});
    return run;
  }

  function enqueueScopeSessionWrite(scope, task) {
    const scopeKey = String(scope?.scopeKey || 'unknown');
    const previous = scopeSessionWriteQueues.get(scopeKey) || Promise.resolve();
    const run = previous.catch(() => {}).then(task);
    const settled = run.finally(() => {
      if (scopeSessionWriteQueues.get(scopeKey) === settled) scopeSessionWriteQueues.delete(scopeKey);
    });
    scopeSessionWriteQueues.set(scopeKey, settled);
    settled.catch(() => {});
    return run;
  }

  function enqueueCoordinatedStateWrite(scope, task) {
    // Lock order is always shared profile/registry first, then one scope session.
    // Scope-only tasks must never wait on the shared coordinator.
    return enqueueSharedProfileRegistryWrite(() => enqueueScopeSessionWrite(scope, task));
  }

  function isScopeSessionWriteBusy(scope) {
    return scopeSessionWriteQueues.has(String(scope?.scopeKey || 'unknown'));
  }

