      frequency: clampInt(source.frequency, 55, 0, 100),
      autonomy: clampInt(source.autonomy, 70, 0, 100),
      goalPersistence: clampInt(source.goalPersistence, 70, 0, 100),
      cooldownTurns: clampInt(source.cooldownTurns, 2, 0, 20),
      maxActorsPerTurn: clampInt(source.maxActorsPerTurn, 2, 1, MAX_ACTIONS_PER_TURN),
      recentMessages: clampInt(source.recentMessages, 14, 4, 40),
      scenePromptMaxChars: clampInt(source.scenePromptMaxChars, DEFAULT_SCENE_PROMPT_CHARS, 10000, MAX_SCENE_PROMPT_CHARS),
      sceneCandidateLimit: clampInt(source.sceneCandidateLimit, DEFAULT_SCENE_CANDIDATES, 1, MAX_SCENE_CANDIDATES),
      maxEvents: clampInt(source.maxEvents, 300, 50, 1000),
      recordHistoryLimit: clampInt(source.recordHistoryLimit, 1800, 200, 5000),
      analysisSourceChunkChars: clampInt(source.analysisSourceChunkChars, 12000, 5000, 24000),
      analysisProfileBatchChars: clampInt(source.analysisProfileBatchChars, 22000, 8000, 44000),
      analysisCharactersPerBatch: clampInt(source.analysisCharactersPerBatch, 4, 1, 10),
      analysisMaxSourceChars: clampInt(source.analysisMaxSourceChars, 0, 0, 100000000),
