      preferenceChangeMode: ['off', 'candidates', 'review', 'auto'].includes(source.preferenceChangeMode) ? source.preferenceChangeMode : 'auto',
      preferenceChangePace: ['cautious', 'standard', 'fast', 'custom'].includes(source.preferenceChangePace) ? source.preferenceChangePace : 'standard',
      preferenceMinEvidence: clampInt(source.preferenceMinEvidence, 2, 1, 20),
      preferenceMinScenes: clampInt(source.preferenceMinScenes, 1, 1, 12),
      preferenceMinConfidence: clampInt(source.preferenceMinConfidence, 80, 0, 100),
      cycleEnabled: source.cycleEnabled !== false,
      cycleDisplay: source.cycleDisplay !== false,
      cycleGoalInfluence: source.cycleGoalInfluence !== false,
      cycleMaxAdjustment: clampInt(source.cycleMaxAdjustment, 5, 0, 5),
      cycleAmplitude: ['low', 'normal', 'high'].includes(source.cycleAmplitude) ? source.cycleAmplitude : 'normal',
