      uiWorkPanel: ['chat', 'screen', 'off'].includes(source.uiWorkPanel) ? source.uiWorkPanel : 'chat',
      uiWorkPanelPos: isPlainObject(source.uiWorkPanelPos) && [source.uiWorkPanelPos.x, source.uiWorkPanelPos.y].every(value => typeof value === 'number' && value >= 0 && value <= 1)
