  async function getLocalStorage() {
    if (localStoragePromise) return await localStoragePromise;
    if (typeof R.getLocalPluginStorage === 'function') {
      localStoragePromise = (async () => {
        const store = await R.getLocalPluginStorage();
        if (!store?.getItem || !store?.setItem) {
          const error = new Error('device-local settings storage returned an invalid adapter');
          error.code = 'EROSYNC_LOCAL_STORAGE_INVALID';
          throw error;
        }
        return store;
      })();
      try {
        return await localStoragePromise;
      } catch (error) {
        localStoragePromise = null;
        warn('device-local settings storage unavailable; the durable adapter will be retried:', error?.message || error);
        throw error;
      }
    }
    localStoragePromise = (async () => {
      if (!localMemoryFallback) {
        const memory = new Map();
        localMemoryFallback = {
          getItem: async (key) => memory.get(key) ?? null,
          setItem: async (key, value) => { memory.set(key, safeClone(value)); },
          removeItem: async (key) => { memory.delete(key); },
        };
        warn('using memory-only settings fallback; provider settings will not survive reload');
      }
      return localMemoryFallback;
    })();
    return await localStoragePromise;
  }

  async function readLegacyArgument(name, fallback = '') {
    if (typeof R.getArgument !== 'function') return fallback;
    try {
      const value = await R.getArgument(name);
      return value === undefined || value === null || value === '' ? fallback : value;
    } catch (_) { return fallback; }
  }

  async function migrateLegacyArguments(config) {
    const legacyMode = clampInt(await readLegacyArgument('erosync_mode', -1), -1, -1, 2);
    if (legacyMode >= 0) config.mode = legacyMode === 0 ? 'off' : legacyMode === 2 ? 'proof' : 'normal';
    const legacyModel = String(await readLegacyArgument('erosync_model', '')).trim();
    const legacyProfileModel = String(await readLegacyArgument('erosync_profile_model', '')).trim();
    const legacyDirectorModel = String(await readLegacyArgument('erosync_director_model', '')).trim();
    if (legacyModel) config.providers.risu.model = legacyModel;
    if (legacyProfileModel) config.profileModel = legacyProfileModel;
    if (legacyDirectorModel) config.directorModel = legacyDirectorModel;
    const strength = clampInt(await readLegacyArgument('erosync_strength', -1), -1, -1, 100);
    if (strength >= 0) config.autonomy = strength;
    const recent = clampInt(await readLegacyArgument('erosync_recent_messages', -1), -1, -1, 40);
    if (recent >= 4) config.recentMessages = recent;
    const debugValue = clampInt(await readLegacyArgument('erosync_debug', -1), -1, -1, 1);
    if (debugValue >= 0) config.debug = debugValue === 1;
    return config;
  }

  async function loadConfig() {
    if (configCache) return configCache;
    let store;
    try {
      store = await getLocalStorage();
    } catch (error) {
      configStorageFault = { status: 'read_failed', value: null, raw: null, error };
      warn('device-local settings adapter could not be opened; Erosync is disabled for this request and no fallback was written');
      return normalizeConfig({ ...DEFAULT_CONFIG, enabled: false });
    }
    const read = await readStorageState(store, LOCAL_CONFIG_KEY);
    if (read.status === 'read_failed' || read.status === 'malformed') {
      configStorageFault = read;
      warn('device-local settings read failed; Erosync is disabled for this request and the stored value was not overwritten:', read.error?.message || read.status);
      return normalizeConfig({ ...DEFAULT_CONFIG, enabled: false });
    }
    if (read.status === 'missing') {
      const migrated = await migrateLegacyArguments(normalizeConfig(DEFAULT_CONFIG));
      try {
        await store.setItem(LOCAL_CONFIG_KEY, migrated);
        configCache = migrated;
        configStorageFault = null;
      } catch (error) {
        warn('device-local settings initialization failed; the runtime fallback was not cached:', error?.message || error);
      }
      return migrated;
    }
    if (!isPlainObject(read.value)) {
      configStorageFault = { ...read, status: 'malformed' };
      warn('device-local settings are malformed; Erosync is disabled for this request and the stored value was not overwritten');
      return normalizeConfig({ ...DEFAULT_CONFIG, enabled: false });
    }
    configCache = normalizeConfig(read.value);
    configStorageFault = null;
    return configCache;
  }

  async function saveConfig(value, options = {}) {
    assertTransferAdmission();
    const transferFence = captureBackgroundFence();
    if (configStorageFault && options.allowStorageRepair !== true) {
      throw storageReadError(LOCAL_CONFIG_KEY, configStorageFault, 'reload the settings or use the confirmed settings reset before overwriting this value');
    }
    const previous = configCache;
    const next = normalizeConfig(value);
    const store = await getLocalStorage();
    assertBackgroundFence(transferFence, 'configuration save');
    try {
      await trackTransferWrite(store.setItem(LOCAL_CONFIG_KEY, next), transferLocalWrites);
      configCache = next;
      configStorageFault = null;
    } catch (error) {
      configCache = previous;
      throw error;
    }
    // 설정 즉시 저장(2026-10-13): 설정 화면에서 온 저장은 계획을 바로 무효로 하되 다시 짜기는 화면을 닫을 때 한 번 한다.
    if (!directorConfigEquivalent(previous, next)) {
      invalidateAllPreparedDecisionState('configuration changed', { replan: options.deferReplan !== true });
      if (options.deferReplan === true) uiSettingsReplanPending = true;
    }
    try {
      await reconcileProfileAuditRetention(configCache.profileAuditLimit);
    } catch (error) {
      warn('profile audit retention reconciliation skipped; settings were saved:', error?.message || error);
    }
    return configCache;
  }

  async function pluginStorageReadState(key) {
    return await readStorageState(R.pluginStorage, key);
  }

  async function pluginStorageGet(key, fallback = null) {
    const read = await pluginStorageReadState(key);
    if (read.status === 'ok') return read.value;
    if (read.status === 'missing') return fallback;
    warn('pluginStorage read failed:', key, read.error?.message || read.status);
    return fallback;
  }

  // 배경음 2단 자료(2026-10-15): 관계망 배경음이 2단으로 바뀔 때 트는 녹음. Ogg Opus 32kbps 스테레오, base64 한 덩어리.
  // 재생은 esSound.tape(00-core)에서 Blob URL + <audio> 둘을 번갈아 써서 통째로 풀지 않는다. 자료 길이·지문은 시험이 확인한다.

  // 같은 키 연속 쓰기 모으기(2026-10-15 버벅임 건의): 한 키의 쓰기가 진행 중일 때 같은 키 쓰기가 또 오면 마지막 값만 남겨 두었다가
  // 앞 쓰기가 끝난 뒤 한 번만 쓴다. 키마다 순서는 그대로이고 끝 상태도 같다(중간 값만 생략). 리스는 저장마다 DB 차이를 계산하므로 횟수가 곧 부담이다.
  // 기다리는 쪽은 자기 값(또는 그 뒤 값)이 실제로 저장된 뒤 풀린다. 실패하면 그 묶음의 기다리는 쪽 모두에게 같은 오류를 돌려준다.
  const pluginStorageInflight = new Map(); // key → { next: { value, capability, waiters: [{resolve, reject}] } | null }
  async function pluginStorageSet(key, value, capability = null) {
    if (exportReadBarrier && capability !== transferStorageCapability) await exportReadBarrier.promise;
    assertSynchronizedStateWritable(key, capability);
    const inflight = pluginStorageInflight.get(key);
    if (inflight) {
      if (!inflight.next) inflight.next = { value, capability, waiters: [] };
      else { inflight.next.value = value; inflight.next.capability = capability; }
      return new Promise((resolve, reject) => inflight.next.waiters.push({ resolve, reject }));
    }
    const entry = { next: null };
    pluginStorageInflight.set(key, entry);
    try {
      await trackTransferWrite(R.pluginStorage.setItem(key, value), transferStorageWrites);
      if (key !== STATE_TX_KEY) uiStorageRevision += 1;
    } finally {
      pluginStorageInflight.delete(key);
      const next = entry.next;
      if (next) {
        pluginStorageSet(key, next.value, next.capability).then(
          result => { for (const waiter of next.waiters) waiter.resolve(result); },
          error => { for (const waiter of next.waiters) waiter.reject(error); },
        );
      }
    }
  }

  async function pluginStorageRemove(key, capability = null) {
    if (exportReadBarrier && capability !== transferStorageCapability) await exportReadBarrier.promise;
    assertSynchronizedStateWritable(key, capability);
    if (typeof R.pluginStorage.removeItem === 'function') await trackTransferWrite(R.pluginStorage.removeItem(key), transferStorageWrites);
    else await trackTransferWrite(R.pluginStorage.setItem(key, null), transferStorageWrites);
    uiStorageRevision += 1;
  }

  function assertSynchronizedStateWritable(key, capability = null) {
    if (unloaded) throw staleLifecycleError('synchronized state write');
    if (transferStorageCapability && capability !== transferStorageCapability) throw staleLifecycleError('backup storage lock');
    if (!stateRecoveryFault || stateRecoveryInProgress || key === STATE_TX_KEY) return;
    const error = new Error('저장 복구가 필요합니다. 복구 표식을 보존한 채 새로고침 후 다시 시도하세요.');
    error.code = 'EROSYNC_STATE_RECOVERY_REQUIRED';
    throw error;
  }

  function requireStateRecovery(error) {
    stateRecoveryFault = {
      code: 'EROSYNC_STATE_RECOVERY_REQUIRED',
      message: '저장 복구를 확인하지 못했습니다. 기존 복구 표식을 보존했습니다.',
      at: new Date().toISOString(),
    };
    invalidateSharedStateCaches();
    // Hook callbacks remain registered so the host request can pass through.
    // All plugin decisions and synchronized writes stop until recovery succeeds.
    invalidateAllPreparedDecisionState('shared-state recovery required');
    return error;
  }

  function emptyStorageManifest() {
    return { schemaVersion: 1, revision: 0, coverage: 'manifest_known_catalog_live_union', sessions: {}, behind: {}, auxiliaryKeys: [], updatedAt: null };
  }

  function normalizeStorageManifest(value) {
    const source = isPlainObject(value) ? value : {};
    const next = emptyStorageManifest();
    next.revision = clampInt(source.revision, 0, 0, 1000000000);
    next.coverage = typeof source.coverage === 'string' || isPlainObject(source.coverage) ? safeClone(source.coverage) : next.coverage;
    next.updatedAt = source.updatedAt || null;
    for (const [scopeKey, raw] of Object.entries(isPlainObject(source.sessions) ? source.sessions : {})) {
      if (!isPlainObject(raw) || !scopeKey) continue;
      const normalizedScopeKey = String(raw.scopeKey || scopeKey);
      if (normalizedScopeKey !== scopeKey) continue;
      const v3Key = String(raw.v3Key ?? `${SESSION_KEY_PREFIX}${scopeKey}`);
      const legacyKey = String(raw.legacyKey ?? `${LEGACY_SESSION_PREFIX}${scopeKey}`);
      if (v3Key && v3Key !== `${SESSION_KEY_PREFIX}${scopeKey}`) continue;
      if (legacyKey && legacyKey !== `${LEGACY_SESSION_PREFIX}${scopeKey}`) continue;
      next.sessions[scopeKey] = {
        sourceBundleKey: String(raw.sourceBundleKey || scopeKey.split(':')[0] || ''),
        scopeKey,
        v3Key,
        legacyKey,
        variantKeys: normalizeStringList(raw.variantKeys, 200, 160).sort(),
        currentVariantKey: String(raw.currentVariantKey || raw.variantKeys?.[0] || 'default'),
        mobProfileIds: normalizeStringList(raw.mobProfileIds, 2000, 180).sort(),
        provenance: typeof raw.provenance === 'string' || Array.isArray(raw.provenance) ? safeClone(raw.provenance) : 'runtime',
      };
      if (next.sessions[scopeKey].variantKeys.length === 0) next.sessions[scopeKey].variantKeys = [next.sessions[scopeKey].currentVariantKey || 'default'];
    }
    for (const [storageKey, raw] of Object.entries(isPlainObject(source.behind) ? source.behind : {})) {
      if (!isPlainObject(raw)) continue;
      const scopeKey = String(raw.scopeKey || '');
      const variantKey = String(raw.variantKey || 'default');
      const expected = `${BEHIND_KEY_PREFIX}${scopeKey}:${variantKey}`;
      if (!scopeKey || storageKey !== expected || (raw.key && raw.key !== expected)) continue;
      next.behind[storageKey] = {
        key: storageKey,
        sourceBundleKey: String(raw.sourceBundleKey || scopeKey.split(':')[0] || ''),
        scopeKey,
        variantKey,
        provenance: typeof raw.provenance === 'string' || Array.isArray(raw.provenance) ? safeClone(raw.provenance) : 'runtime',
      };
    }
    next.auxiliaryKeys = normalizeStringList(Array.isArray(source.auxiliaryKeys) ? source.auxiliaryKeys : [], 5000, 260).sort();
    return next;
  }

  async function loadStorageManifest() {
    if (storageManifestCache) return storageManifestCache;
    const read = requireReadableStorageState(STORAGE_MANIFEST_KEY, await pluginStorageReadState(STORAGE_MANIFEST_KEY), (value) => isPlainObject(value));
    storageManifestCache = read.status === 'missing' ? emptyStorageManifest() : normalizeStorageManifest(read.value);
    return storageManifestCache;
  }

  async function mutateStorageManifest(label, mutator) {
    const run = async () => {
      const read = requireReadableStorageState(STORAGE_MANIFEST_KEY, await pluginStorageReadState(STORAGE_MANIFEST_KEY), (value) => isPlainObject(value));
      const current = read.status === 'missing' ? emptyStorageManifest() : normalizeStorageManifest(read.value);
      const next = safeClone(current) || current;
      mutator(next);
      const normalized = normalizeStorageManifest(next);
      const beforeComparable = JSON.stringify({ coverage: current.coverage, sessions: current.sessions, behind: current.behind, auxiliaryKeys: current.auxiliaryKeys });
      const afterComparable = JSON.stringify({ coverage: normalized.coverage, sessions: normalized.sessions, behind: normalized.behind, auxiliaryKeys: normalized.auxiliaryKeys });
      if (beforeComparable === afterComparable) {
        storageManifestCache = current;
        return current;
      }
      normalized.revision = current.revision + 1;
      normalized.updatedAt = new Date().toISOString();
      await pluginStorageSet(STORAGE_MANIFEST_KEY, normalized);
      const readback = requireReadableStorageState(STORAGE_MANIFEST_KEY, await pluginStorageReadState(STORAGE_MANIFEST_KEY), (value) => isPlainObject(value));
      const durable = normalizeStorageManifest(readback.value);
      if (durableValueHash(durable) !== durableValueHash(normalized)) throw new Error(`${label} manifest readback mismatch`);
      storageManifestCache = durable;
      return durable;
    };
    const task = storageManifestWriteQueue.then(run, run);
    storageManifestWriteQueue = task.catch(() => {});
    return await task;
  }

  function mergeOwnedScopeRecord(target, value) {
    const variants = normalizeStringList([...(target.variantKeys || []), ...(value.variantKeys || []), value.currentVariantKey], 200, 160).sort();
    target.sourceBundleKey = String(value.sourceBundleKey || target.sourceBundleKey || value.scopeKey?.split(':')[0] || '');
    target.scopeKey = String(value.scopeKey || target.scopeKey || '');
    if (value.v3Key !== undefined) target.v3Key = String(value.v3Key);
    else if (target.v3Key === undefined) target.v3Key = `${SESSION_KEY_PREFIX}${target.scopeKey}`;
    if (value.legacyKey !== undefined) target.legacyKey = String(value.legacyKey);
    else if (target.legacyKey === undefined) target.legacyKey = `${LEGACY_SESSION_PREFIX}${target.scopeKey}`;
    target.variantKeys = variants.length > 0 ? variants : ['default'];
    target.currentVariantKey = String(value.currentVariantKey || target.currentVariantKey || target.variantKeys[0] || 'default');
    target.mobProfileIds = normalizeStringList([...(target.mobProfileIds || []), ...(value.mobProfileIds || [])], 2000, 180).sort();
    target.provenance = target.provenance || value.provenance || 'runtime';
    return target;
  }

  async function ensureSessionOwnership(scope, options = {}) {
    if (!scope?.scopeKey || !scope?.sourceBundleKey) throw new Error('session ownership requires an exact scope');
    return await mutateStorageManifest('session ownership', (manifest) => {
      const current = manifest.sessions[scope.scopeKey] || {};
      manifest.sessions[scope.scopeKey] = mergeOwnedScopeRecord(current, {
        sourceBundleKey: scope.sourceBundleKey,
        scopeKey: scope.scopeKey,
        v3Key: options.v3Key !== undefined ? options.v3Key : `${SESSION_KEY_PREFIX}${scope.scopeKey}`,
        legacyKey: options.legacyKey !== undefined ? options.legacyKey : `${LEGACY_SESSION_PREFIX}${scope.scopeKey}`,
        variantKeys: [scope.variantKey || options.variantKey || 'default'],
        currentVariantKey: scope.variantKey || options.variantKey || 'default',
        mobProfileIds: options.mobProfileIds || [],
        provenance: options.provenance || 'runtime',
      });
    });
  }

  async function ensureBehindOwnership(scope, variantKey = 'default') {
    const key = `${BEHIND_KEY_PREFIX}${scope.scopeKey}:${String(variantKey || 'default')}`;
    await ensureSessionOwnership(scope, { variantKey, provenance: 'behind' });
    return await mutateStorageManifest('Behind ownership', (manifest) => {
      manifest.behind[key] = manifest.behind[key] || { key, sourceBundleKey: scope.sourceBundleKey, scopeKey: scope.scopeKey, variantKey: String(variantKey || 'default'), provenance: 'runtime' };
    });
  }

  async function enumerateOwnedScopes({ sourceBundleKey = '', scopeKey = '', strict = true } = {}) {
    const manifest = strict ? normalizeStorageManifest((await requireReadableStorageState(STORAGE_MANIFEST_KEY, await pluginStorageReadState(STORAGE_MANIFEST_KEY), (value) => isPlainObject(value))).value || {}) : normalizeStorageManifest(await pluginStorageGet(STORAGE_MANIFEST_KEY, {}));
    const catalog = strict ? normalizeScopeCatalog((await requireReadableStorageState(SCOPE_CATALOG_KEY, await pluginStorageReadState(SCOPE_CATALOG_KEY), (value) => isPlainObject(value))).value || {}) : normalizeScopeCatalog(await pluginStorageGet(SCOPE_CATALOG_KEY, {}));
    const scopes = new Map();
    const add = (value) => {
      if (!value?.scopeKey) return;
      if (sourceBundleKey && value.sourceBundleKey !== sourceBundleKey) return;
      if (scopeKey && value.scopeKey !== scopeKey) return;
      const current = scopes.get(value.scopeKey) || { sourceBundleKey: value.sourceBundleKey || '', scopeKey: value.scopeKey, v3Key: '', legacyKey: '', variantKeys: [], mobProfileIds: [], behindKeys: [], provenance: [] };
      mergeOwnedScopeRecord(current, value);
      current.provenance = normalizeStringList([...(Array.isArray(current.provenance) ? current.provenance : [current.provenance]), ...(Array.isArray(value.provenance) ? value.provenance : [value.provenance])], 20, 80).sort();
      scopes.set(value.scopeKey, current);
    };
    for (const entry of Object.values(manifest.sessions || {})) add(entry);
    for (const bot of Object.values(catalog.bots || {})) {
      for (const chat of Object.values(bot.chats || {})) add({ sourceBundleKey: bot.sourceBundleKey, scopeKey: chat.scopeKey, v3Key: `${SESSION_KEY_PREFIX}${chat.scopeKey}`, legacyKey: `${LEGACY_SESSION_PREFIX}${chat.scopeKey}`, variantKeys: [chat.variantKey || 'default'], currentVariantKey: chat.variantKey || 'default', provenance: 'catalog' });
    }
    for (const [key, entry] of Object.entries(manifest.behind || {})) {
      add({ sourceBundleKey: entry.sourceBundleKey, scopeKey: entry.scopeKey, variantKeys: [entry.variantKey], provenance: 'behind' });
      const current = scopes.get(entry.scopeKey);
      if (current && !current.behindKeys.includes(key)) current.behindKeys.push(key);
    }
    const result = [...scopes.values()].map((entry) => ({ ...entry, variantKeys: [...new Set(entry.variantKeys)].sort(), mobProfileIds: [...new Set(entry.mobProfileIds)].sort(), behindKeys: [...new Set(entry.behindKeys)].sort() })).sort((left, right) => left.scopeKey.localeCompare(right.scopeKey));
    return { scopes: result, coverage: manifest.coverage || 'manifest_known_catalog_live_union', warnings: [] };
  }

  async function reconcileStorageManifestOwnership() {
    const enumerated = await enumerateOwnedScopes({ strict: true });
    const registry = await loadRegistry();
    return await mutateStorageManifest('ownership backfill', (manifest) => {
      for (const entry of enumerated.scopes) {
        const mobProfileIds = Object.values(registry.entities || {}).filter((entity) => entity?.scopeKey === entry.scopeKey && ['temporary_mob', 'persistent_mob'].includes(entity.category)).map((entity) => entity.profileId || entity.id);
        manifest.sessions[entry.scopeKey] = mergeOwnedScopeRecord(manifest.sessions[entry.scopeKey] || {}, { ...entry, mobProfileIds, provenance: manifest.sessions[entry.scopeKey]?.provenance || 'catalog_backfill' });
      }
    });
  }

  async function repairMobScopeOwnership() {
    const manifest = await loadStorageManifest();
    const profiles = await loadProfileStore();
    const registry = await loadRegistry();
    const mobProfiles = Object.values(profiles.profiles || {}).filter((profile) => ['temporary_mob', 'persistent_mob'].includes(profile?.category));
    const needsRepair = mobProfiles.some((profile) => !registry.entities?.[profile.id]?.scopeKey && !registry.entities?.[profile.id]?.excludedFromDirector);
    if (!needsRepair) return false;
    await mutateProfileRegistry('mob scope ownership recovery', (freshProfiles, freshRegistry) => {
      for (const profile of Object.values(freshProfiles.profiles || {})) {
        if (!['temporary_mob', 'persistent_mob'].includes(profile?.category)) continue;
        const manifestScopes = Object.values(manifest.sessions || {}).filter((entry) => (entry.mobProfileIds || []).includes(profile.id)).map((entry) => entry.scopeKey);
        const exactScopes = normalizeStringList([profile.scopeOwnership?.confidence === 'exact' ? profile.scopeOwnership.scopeKey : '', ...manifestScopes], 20, 220);
        const uniqueScopes = [...new Set(exactScopes.filter(Boolean))];
        const entity = freshRegistry.entities[profile.id] || { id: profile.id, name: profile.name, aliases: profile.aliases || [], category: profile.category, source: 'manifest_recovery', profileId: profile.id, firstSeenTurn: 0, lastSeenTurn: 0, appearanceCount: 0 };
        if (uniqueScopes.length === 1) {
          const owned = manifest.sessions?.[uniqueScopes[0]];
          entity.scopeKey = uniqueScopes[0];
          entity.category = profile.category;
          entity.excludedFromDirector = false;
          profile.scopeOwnership = { scopeKey: uniqueScopes[0], sourceBundleKey: owned?.sourceBundleKey || profile.ownerBundleKeys?.[0] || '', firstSeenTurn: profile.scopeOwnership?.firstSeenTurn || 0, lastSeenTurn: profile.scopeOwnership?.lastSeenTurn || 0, confidence: 'exact' };
          profile.excludedFromDirector = false;
        } else {
          entity.scopeKey = '';
          entity.excludedFromDirector = true;
          entity.scopeRecoveryStatus = uniqueScopes.length > 1 ? 'ambiguous' : 'unknown';
          profile.excludedFromDirector = true;
        }
        freshRegistry.entities[profile.id] = entity;
      }
    });
    return true;
  }

  function durableValueHash(value) {
    return fnv1a(JSON.stringify(value === undefined ? null : value));
  }

  function invalidateSharedStateCaches() {
    invalidateUiInventory();
    profileStoreCache = null;
    registryCache = null;
    scopeCatalogCache = null;
  }

  async function strictDurableRead(key) {
    return requireReadableStorageState(key, await pluginStorageReadState(key));
  }

  async function restoreTransactionBefore(marker, targetKeys = null, options = {}) {
    const allowed = targetKeys ? new Set(targetKeys) : null;
    const entries = (Array.isArray(marker?.entries) ? marker.entries : []).filter((entry) => !allowed || allowed.has(entry?.key));
    for (const entry of entries) {
      if (!entry?.key) continue;
      await strictDurableRead(entry.key);
    }
    for (const entry of entries) {
      if (!entry?.key) continue;
      if (entry.beforeStatus === 'missing') await pluginStorageRemove(entry.key, options.capability);
      else await pluginStorageSet(entry.key, safeClone(entry.beforeValue), options.capability);
    }
    for (const entry of entries) {
      const read = await strictDurableRead(entry.key);
      const hash = read.status === 'missing' ? durableValueHash(null) : durableValueHash(read.value);
      if (hash !== entry.beforeHash) throw new Error(`transaction rollback readback mismatch: ${entry.key}`);
    }
  }

  async function recoverPendingStateTransaction() {
    stateRecoveryInProgress = true;
    try {
      const read = requireReadableStorageState(STATE_TX_KEY, await pluginStorageReadState(STATE_TX_KEY), (value) => isPlainObject(value) && Array.isArray(value.entries));
      if (read.status === 'missing') return false;
      const marker = read.value;
      invalidateSharedStateCaches();
      const currentStates = new Map();
      for (const entry of marker.entries) currentStates.set(entry.key, await strictDurableRead(entry.key));
      if (marker.phase === 'committed') {
        let committed = true;
        for (const entry of marker.entries) {
          const current = currentStates.get(entry.key);
          const hash = current.status === 'missing' ? durableValueHash(null) : durableValueHash(current.value);
          if (hash !== entry.afterHash) { committed = false; break; }
        }
        if (committed) {
          await pluginStorageRemove(STATE_TX_KEY);
          stateRecoveryFault = null;
          return true;
        }
      }
      await restoreTransactionBefore(marker);
      await pluginStorageRemove(STATE_TX_KEY);
      invalidateSharedStateCaches();
      stateRecoveryFault = null;
      return true;
    } catch (error) {
      requireStateRecovery(error);
      warn('pending shared-state transaction could not be recovered; core hooks remain inactive and the original marker was preserved:', error?.message || error);
      return false;
    } finally {
      stateRecoveryInProgress = false;
    }
  }

  async function commitStateTransactionWithinLock(label, writes, options = {}) {
    if (stateRecoveryFault && (!transferStorageCapability || options.capability !== transferStorageCapability)) {
      const error = new Error('shared state is awaiting transaction recovery; mutation was blocked');
      error.code = 'EROSYNC_STATE_RECOVERY_REQUIRED';
      throw error;
    }
    const writeMap = new Map();
    for (const entry of (Array.isArray(writes) ? writes : [])) if (entry?.key) writeMap.set(entry.key, entry);
    const normalizedWrites = [...writeMap.values()];
    if (normalizedWrites.length === 0) return {};
    if (options.fence) assertBackgroundFence(options.fence, `${label} transaction start`);
    const entries = [];
    for (const write of normalizedWrites) {
      const before = await strictDurableRead(write.key);
      const beforeValue = before.status === 'missing' ? null : safeClone(before.value);
      const afterValue = write.remove === true ? null : safeClone(write.value);
      entries.push({
        key: write.key,
        beforeStatus: before.status,
        beforeValue,
        beforeHash: durableValueHash(beforeValue),
        afterHash: durableValueHash(afterValue),
      });
    }
    const marker = {
      schemaVersion: 1,
      id: `tx_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
      label: truncate(label, 120),
      phase: 'prepared',
      entries,
      startedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    await pluginStorageSet(STATE_TX_KEY, marker, options.capability);
    if (options.compactProgress === true) {
      const storedMarker = await strictDurableRead(STATE_TX_KEY);
      if (storedMarker.status !== 'ok' || backupCodec.canonicalStringify(storedMarker.value) !== backupCodec.canonicalStringify(marker)) throw new Error('BACKUP_TRANSACTION_MARKER_READBACK');
    }
    const durable = {};
    const attemptedKeys = [];
    try {
      for (let index = 0; index < normalizedWrites.length; index += 1) {
        if (options.fence) assertBackgroundFence(options.fence, `${label} transaction write ${index + 1}`);
        const write = normalizedWrites[index];
        attemptedKeys.push(write.key);
        if (write.remove === true) await pluginStorageRemove(write.key, options.capability);
        else await pluginStorageSet(write.key, write.value, options.capability);
        marker.phase = `written_${index + 1}`;
        marker.updatedAt = new Date().toISOString();
        // markerOnce: 복구 기록을 시작·끝에만 저장한다(복구는 'committed'만 보고 나머지는 전부 되돌리므로 중간 진행 기록은 쓰이지 않는다).
        // 키가 많은 데이터 초기화에서 큰 기록을 키마다 다시 저장하던 부담을 없앤다(2026-10-12 핫픽스).
        if (options.compactProgress !== true && options.markerOnce !== true) await pluginStorageSet(STATE_TX_KEY, marker, options.capability);
      }
      for (const entry of entries) {
        const readback = await strictDurableRead(entry.key);
        const value = readback.status === 'missing' ? null : readback.value;
        if (durableValueHash(value) !== entry.afterHash) throw new Error(`transaction readback mismatch: ${entry.key}`);
        durable[entry.key] = value;
      }
      if (options.fence) assertBackgroundFence(options.fence, `${label} transaction readback`);
      marker.phase = 'committed';
      marker.updatedAt = new Date().toISOString();
      await pluginStorageSet(STATE_TX_KEY, marker, options.capability);
      await pluginStorageRemove(STATE_TX_KEY, options.capability);
      if (Object.prototype.hasOwnProperty.call(durable, PROFILE_STORE_KEY)) profileStoreCache = normalizeProfileStore(durable[PROFILE_STORE_KEY]);
      if (Object.prototype.hasOwnProperty.call(durable, REGISTRY_STORE_KEY)) registryCache = normalizeRegistryStore(durable[REGISTRY_STORE_KEY]);
      if (Object.prototype.hasOwnProperty.call(durable, SCOPE_CATALOG_KEY)) scopeCatalogCache = normalizeScopeCatalog(durable[SCOPE_CATALOG_KEY]);
      if (Object.prototype.hasOwnProperty.call(durable, STORAGE_MANIFEST_KEY)) storageManifestCache = normalizeStorageManifest(durable[STORAGE_MANIFEST_KEY]);
      return durable;
    } catch (error) {
      invalidateSharedStateCaches();
      if (unloaded && options.fence) {
        error.transactionPendingRecovery = true;
        throw error;
      }
      try {
        if (attemptedKeys.length > 0) await restoreTransactionBefore(marker, attemptedKeys, options);
        await pluginStorageRemove(STATE_TX_KEY, options.capability);
      } catch (restoreError) {
        requireStateRecovery(restoreError);
        try {
          await pluginStorageSet(STATE_TX_KEY, { ...marker, phase: 'recovery_failed', recoveryError: 'Rollback verification failed', updatedAt: new Date().toISOString() }, options.capability);
        } catch (_) {}
        error.recoveryError = restoreError;
      }
      throw error;
    }
  }

  function emptyScopeCatalog() {
    return { schemaVersion: SCOPE_CATALOG_SCHEMA, bots: {}, updatedAt: null };
  }

  function normalizeScopeCatalog(value) {
    const source = isPlainObject(value) ? value : {};
    const next = emptyScopeCatalog();
    for (const [botKey, rawBot] of Object.entries(isPlainObject(source.bots) ? source.bots : {})) {
      if (!isPlainObject(rawBot)) continue;
      const bot = {
        sourceBundleKey: String(rawBot.sourceBundleKey || botKey),
        characterId: String(rawBot.characterId || ''),
        characterName: truncate(rawBot.characterName || rawBot.name || botKey, 200),
        lastScopeKey: String(rawBot.lastScopeKey || ''),
        lastSeenAt: rawBot.lastSeenAt || null,
        profileCount: clampInt(rawBot.profileCount, 0, 0, 100000),
        chats: {},
      };
      for (const [scopeKey, rawChat] of Object.entries(isPlainObject(rawBot.chats) ? rawBot.chats : {})) {
        if (!isPlainObject(rawChat)) continue;
        bot.chats[scopeKey] = {
          scopeKey,
          sourceBundleKey: bot.sourceBundleKey,
          chatId: String(rawChat.chatId || ''),
          chatName: truncate(rawChat.chatName || rawChat.name || scopeKey, 220),
          characterIndex: clampInt(rawChat.characterIndex, -1, -1, 100000),
          chatIndex: clampInt(rawChat.chatIndex, -1, -1, 100000),
          lastUpdatedAt: rawChat.lastUpdatedAt || null,
          turnIndex: clampInt(rawChat.turnIndex, 0, 0, 100000000),
          eventCount: clampInt(rawChat.eventCount, 0, 0, 10000000),
          interactionCount: clampInt(rawChat.interactionCount, 0, 0, 10000000),
          activeGoalCount: clampInt(rawChat.activeGoalCount, 0, 0, 1000000),
          mobCount: clampInt(rawChat.mobCount, 0, 0, 1000000),
          variantKey: String(rawChat.variantKey || ''),
          variantLabel: truncate(rawChat.variantLabel || '', 160),
          variantSignature: String(rawChat.variantSignature || rawChat.activationSignature || ''),
          sourceHash: String(rawChat.sourceHash || ''),
        };
      }
      if (bot.lastScopeKey && !bot.chats[bot.lastScopeKey]) bot.lastScopeKey = '';
      if (!bot.lastScopeKey) bot.lastScopeKey = Object.values(bot.chats).sort((left, right) => String(right.lastUpdatedAt || '').localeCompare(String(left.lastUpdatedAt || '')))[0]?.scopeKey || '';
      next.bots[bot.sourceBundleKey] = bot;
    }
    next.updatedAt = source.updatedAt || null;
    return next;
  }

  async function loadScopeCatalog() {
    if (scopeCatalogCache) return scopeCatalogCache;
    const read = requireReadableStorageState(SCOPE_CATALOG_KEY, await pluginStorageReadState(SCOPE_CATALOG_KEY), (value) => isPlainObject(value) && (value.bots === undefined || isPlainObject(value.bots)));
    scopeCatalogCache = read.status === 'missing' ? emptyScopeCatalog() : normalizeScopeCatalog(read.value);
    if (read.status === 'ok' && Number(read.value?.schemaVersion || 0) !== SCOPE_CATALOG_SCHEMA) {
      debug(configCache || DEFAULT_CONFIG, 'scope catalog was normalized to the current schema in memory; the next catalog mutation will persist it');
    }
    return scopeCatalogCache;
  }

  async function saveScopeCatalog(catalog) {
    const next = normalizeScopeCatalog(catalog);
    next.updatedAt = new Date().toISOString();
    try {
      await pluginStorageSet(SCOPE_CATALOG_KEY, next);
      const readback = requireReadableStorageState(SCOPE_CATALOG_KEY, await pluginStorageReadState(SCOPE_CATALOG_KEY), (value) => isPlainObject(value) && (value.bots === undefined || isPlainObject(value.bots)));
      scopeCatalogCache = normalizeScopeCatalog(readback.value);
      return scopeCatalogCache;
    } catch (error) {
      scopeCatalogCache = null;
      throw error;
    }
  }

  function normalizeRosterDiscovery(value) {
    const source = isPlainObject(value) ? value : {};
    return {
      schemaVersion: 1,
      selectedEntries: (Array.isArray(source.selectedEntries) ? source.selectedEntries : []).filter(isPlainObject).slice(0, 1000).map(entry => ({
        id: String(entry.id || ''), hash: String(entry.hash || ''), title: truncate(entry.title, 240),
      })).filter(entry => entry.id),
      confirmed: source.confirmed === true,
      aiFallback: source.aiFallback !== false,
      includeGlobalToggles: source.includeGlobalToggles === true,
      rosterDropGlobalToggles: source.rosterDropGlobalToggles === true,
      people: (Array.isArray(source.people) ? source.people : []).filter(isPlainObject).slice(0, MAX_PROFILE_CHARACTERS).map(person => ({
        key: String(person.key || rosterParser.normalizeName(person.name)),
        name: truncate(person.name, 180),
        aliases: normalizeStringList(person.aliases, 80, 180),
        activationKeys: normalizeStringList(person.activationKeys, 80, 180),
        section: truncate(person.section, 240),
        rosterEntryId: String(person.rosterEntryId || ''),
        sourceBlock: String(person.sourceBlock || '').slice(0, 200000),
        matchedLoreId: String(person.matchedLoreId || ''),
        matchHow: ['full', 'part'].includes(person.matchHow) ? person.matchHow : 'none',
      })).filter(person => person.name && person.sourceBlock),
      inspectedAt: source.inspectedAt || null,
    };
  }

  const ANALYSIS_WORKFLOWS = Object.freeze(['roster', 'selected_lore', 'full']);

  

  function normalizeLoreSelection(value) {
    const raw = isPlainObject(value) ? value : {}, seen = new Set();
    // solo: the user keeps this source apart from other sources with the same activation keys.
    const selectedEntries = (Array.isArray(raw.selectedEntries) ? raw.selectedEntries : []).filter(isPlainObject).slice(0, MAX_PROFILE_CHARACTERS).map(entry => ({
      id: truncate(entry.id, 180), hash: truncate(entry.hash, 100), title: truncate(entry.title, 240), ...(entry.solo === true ? { solo: true } : {}),
    })).filter(entry => entry.id && !seen.has(entry.id) && seen.add(entry.id));
    return { schemaVersion: 1, revision: clampInt(raw.revision, 0, 0, 1000000000), selectedEntries };
  }

  function normalizeSelectedLoreProfile(value) {
    if (!isPlainObject(value)) return null;
    return { entries: normalizeLoreSelection({ selectedEntries: value.entries }).selectedEntries.map(({ id, hash }) => ({ id, hash })) };
  }

  function selectedLoreSelectionKey(value) {
    return fnv1a(JSON.stringify(normalizeLoreSelection(value).selectedEntries.map(entry => entry.id).sort()));
  }

  const RELATION_CHANGE_FIELDS = Object.freeze(['affection', 'eroticAttraction', 'hatred']);

  function parseRelationChangeMultiplier(value) {
    if (!['number', 'string'].includes(typeof value) || String(value).trim() === '') return null;
    const number = Number(value), tenths = Math.round(number * 10);
    if (!Number.isFinite(number) || number < 0 || number > 3 || Math.abs(number * 10 - tenths) > 1e-8) return null;
    return tenths / 10;
  }

  function normalizeRelationChangeMultipliers(value) {
    return Object.fromEntries(RELATION_CHANGE_FIELDS.map(field => [field, parseRelationChangeMultiplier(value?.[field]) ?? 1]));
  }

  function relationChangePlanningSettings(botOverride) {
    const values = normalizeRelationChangeMultipliers(botOverride?.relationChangeMultipliers);
    if (botOverride?.domains?.conflict !== true) values.hatred = 1;
    return RELATION_CHANGE_FIELDS.some(field => values[field] !== 1) ? values : null;
  }

  // 봇별 극단 행동 수위 · SFW/NSFW · NSFW+ · 재검사 (0.8.6). 기본값은 0.8.5와 같은 동작이다.
  const EXTREMITY_LIMITS = Object.freeze({
    off: { cap: null, label: '사용 안 함' },
    // 화면 이름은 정의학의 극단성 구간 이름과 맞춘다. 키와 상한값(저장값)은 그대로다.
    moderate: { cap: 20, label: '대화 안에서만' },
    pressure: { cap: 40, label: '비물리적 압박까지' },
    indirect: { cap: 60, label: '위협·통제·경미한 손실까지' },
    direct: { cap: 80, label: '폭력·감금·강압까지' },
    unlimited: { cap: 100, label: '제한 없음' },
  });
  const EXTREMITY_LIMIT_KEYS = Object.freeze(Object.keys(EXTREMITY_LIMITS));
  function normalizeExtremityLimit(value) {
    return Object.prototype.hasOwnProperty.call(EXTREMITY_LIMITS, value) ? value : 'unlimited';
  }
  function normalizeContentMode(value) {
    return value === 'sfw' ? 'sfw' : 'nsfw';
  }
  // 장면 판단 AI와 지시문에 무엇을 보낼지 정하는 봇 단위 정책. NSFW+는 NSFW이고 수위가 제한 없음일 때만 유효하다.
  function contentPolicyFor(botOverride) {
    const contentMode = normalizeContentMode(botOverride?.contentMode);
    const extremityLimit = normalizeExtremityLimit(botOverride?.extremityLimit);
    const nsfwPlus = contentMode === 'nsfw' && extremityLimit === 'unlimited' && botOverride?.nsfwPlus === true;
    return {
      contentMode,
      extremityLimit,
      extremityCap: EXTREMITY_LIMITS[extremityLimit].cap,
      nsfwPlus,
      recheck: nsfwPlus && botOverride?.nsfwPlusRecheck === true,
      tag: contentMode === 'sfw' ? 'SFW' : nsfwPlus ? 'NSFW+' : 'NSFW',
    };
  }
  // 수위 상한을 적용한 극단성. 값이 없거나 수위가 "사용 안 함"이면 undefined(보내지 않음).
  function cappedExtremity(value, policy) {
    if (!Number.isFinite(value) || !policy || policy.extremityCap === null) return undefined;
    return Math.min(Math.round(value), policy.extremityCap);
  }
  // SFW에서는 행동 모드 이름을 농담/다가가기로 주고받고 저장할 때는 기존 키로 되돌린다.
  const SFW_MODE_OUT = Object.freeze({ sexual_humor: 'humor', seduce: 'approach' });
  const SFW_MODE_IN = Object.freeze({ humor: 'sexual_humor', approach: 'seduce' });
  function storedModeKey(value) {
    const text = String(value || '');
    return SFW_MODE_IN[text] || text;
  }
  function directorModeName(value, policy) {
    const text = String(value || '');
    return policy?.contentMode === 'sfw' ? SFW_MODE_OUT[text] || text : text;
  }
  function sfwDirectorView(value, policy, depth = 0) {
    if (policy?.contentMode !== 'sfw' || depth > 8) return value;
    if (Array.isArray(value)) return value.map(item => sfwDirectorView(item, policy, depth + 1));
    if (!isPlainObject(value)) return value;
    const result = {};
    for (const [key, item] of Object.entries(value)) result[key] = key === 'mode' && typeof item === 'string' ? directorModeName(item, policy) : sfwDirectorView(item, policy, depth + 1);
    return result;
  }

  function normalizeBotOverrideStore(value) {
    const source = isPlainObject(value) ? value : {};
    const next = { schemaVersion: 1, bots: {}, updatedAt: source.updatedAt || null };
    for (const [bundleKey, raw] of Object.entries(isPlainObject(source.bots) ? source.bots : {})) {
      if (!isPlainObject(raw)) continue;
      const hasConflictChoice = isPlainObject(raw.domains) && Object.prototype.hasOwnProperty.call(raw.domains, 'conflict');
      const savedConflictProvenance = ['user', 'default_v2', 'legacy_preserved'].includes(raw.domainProvenance?.conflict)
        ? raw.domainProvenance.conflict
        : '';
      const conflict = savedConflictProvenance === 'default_v2'
        ? raw.domains?.conflict !== false
        : hasConflictChoice ? raw.domains.conflict === true : true;
      const conflictProvenance = savedConflictProvenance || (hasConflictChoice ? 'legacy_preserved' : 'default_v2');
      next.bots[bundleKey] = {
        koco: normalizeKocoOptions(raw.koco),
        analysisWorkflow: ANALYSIS_WORKFLOWS.includes(raw.analysisWorkflow) ? raw.analysisWorkflow : '',
        loreSelection: normalizeLoreSelection(raw.loreSelection),
        relationChangeMultipliers: normalizeRelationChangeMultipliers(raw.relationChangeMultipliers),
        narrativePreset: raw.narrativePreset === 'political_strategy' ? 'political_strategy' : 'general',
        domains: {
          intimacy: raw.domains?.intimacy !== false,
          conflict,
        },
        domainProvenance: { conflict: conflictProvenance },
        extremityLimit: normalizeExtremityLimit(raw.extremityLimit),
        contentMode: normalizeContentMode(raw.contentMode),
        nsfwPlus: raw.nsfwPlus === true,
        nsfwPlusRecheck: raw.nsfwPlusRecheck === true,
        sexualTargets: normalizeSexualTargetSettings(raw.sexualTargets),
        activeVariantKey: String(raw.activeVariantKey || 'default'),
        rosterDiscovery: normalizeRosterDiscovery(raw.rosterDiscovery),
        analysisModules: {
          schemaVersion: 1,
          revision: clampInt(raw.analysisModules?.revision, 0, 0, 1000000000),
          excludedKeys: normalizeStringList(raw.analysisModules?.excludedKeys, 1000, 240).sort(),
          keyMetadata: Object.fromEntries(Object.entries(isPlainObject(raw.analysisModules?.keyMetadata) ? raw.analysisModules.keyMetadata : {}).filter(([key, meta]) => key && isPlainObject(meta)).slice(0, 1000).map(([key, meta]) => [key, {
            keyVersion: clampInt(meta.keyVersion, 1, 1, 10),
            identityKind: String(meta.identityKind || meta.origin || ''),
            identityValue: truncate(meta.identityValue || '', 240),
            ownerKind: truncate(meta.ownerKind || '', 80),
            ownerId: truncate(meta.ownerId || '', 240),
            contentFingerprint: String(meta.contentFingerprint || ''),
            nameAtExclusion: truncate(meta.nameAtExclusion || meta.name || key, 200),
            embedded: meta.embedded === true,
            excludedAt: meta.excludedAt || meta.lastSeenAt || null,
          }])),
          updatedAt: raw.analysisModules?.updatedAt || null,
        },
        updatedAt: raw.updatedAt || null,
      };
    }
    return next;
  }

  async function loadBotOverrides() {
    if (botOverrideCache) return botOverrideCache;
    const read = requireReadableStorageState(BOT_OVERRIDE_STORE_KEY, await pluginStorageReadState(BOT_OVERRIDE_STORE_KEY), (value) => isPlainObject(value) && (value.bots === undefined || isPlainObject(value.bots)));
    botOverrideCache = read.status === 'missing' ? normalizeBotOverrideStore(null) : normalizeBotOverrideStore(read.value);
    const needsConflictProvenanceMigration = read.status === 'ok' && Object.values(read.value?.bots || {}).some((bot) => !['user', 'default_v2', 'legacy_preserved'].includes(bot?.domainProvenance?.conflict));
    if (needsConflictProvenanceMigration) await pluginStorageSet(BOT_OVERRIDE_STORE_KEY, botOverrideCache);
    return botOverrideCache;
  }

  async function saveBotOverrides(value) {
    const previous = requireReadableStorageState(BOT_OVERRIDE_STORE_KEY, await pluginStorageReadState(BOT_OVERRIDE_STORE_KEY));
    const next = normalizeBotOverrideStore(value);
    next.updatedAt = new Date().toISOString();
    try {
      await pluginStorageSet(BOT_OVERRIDE_STORE_KEY, next);
      botOverrideCache = next;
      invalidateUiInventory();
      if (botPlanningInputs(previous.value) !== botPlanningInputs(next)) invalidateAllPreparedDecisionState('bot settings changed', { replan: true });
      return botOverrideCache;
    } catch (error) {
      botOverrideCache = null;
      throw error;
    }
  }

  async function getBotOverride(sourceBundleKey) {
    const store = await loadBotOverrides();
    return store.bots[sourceBundleKey] || {
      koco: normalizeKocoOptions(null),
      analysisWorkflow: '',
      loreSelection: normalizeLoreSelection(null),
      relationChangeMultipliers: normalizeRelationChangeMultipliers(null),
      narrativePreset: 'general',
      domains: { intimacy: true, conflict: true },
      domainProvenance: { conflict: 'default_v2' },
      extremityLimit: 'unlimited',
      contentMode: 'nsfw',
      nsfwPlus: false,
      nsfwPlusRecheck: false,
      sexualTargets: normalizeSexualTargetSettings(null),
      activeVariantKey: 'default',
      rosterDiscovery: normalizeRosterDiscovery(null),
      analysisModules: { schemaVersion: 1, revision: 0, excludedKeys: [], keyMetadata: {}, updatedAt: null },
      updatedAt: null,
    };
  }

  async function updateBotOverride(sourceBundleKey, patch) {
    assertTransferAdmission();
    const transferFence = captureBackgroundFence();
    const store = await loadBotOverrides();
    const current = await getBotOverride(sourceBundleKey);
    assertBackgroundFence(transferFence, 'bot settings save');
    const conflictExplicitlyPatched = isPlainObject(patch?.domains) && Object.prototype.hasOwnProperty.call(patch.domains, 'conflict');
    store.bots[sourceBundleKey] = {
      ...current,
      ...(isPlainObject(patch) ? patch : {}),
      domains: { ...current.domains, ...(isPlainObject(patch?.domains) ? patch.domains : {}) },
      relationChangeMultipliers: normalizeRelationChangeMultipliers({ ...current.relationChangeMultipliers,
        ...(isPlainObject(patch?.relationChangeMultipliers) ? patch.relationChangeMultipliers : {}) }),
      sexualTargets: normalizeSexualTargetSettings({ ...current.sexualTargets, ...(isPlainObject(patch?.sexualTargets) ? patch.sexualTargets : {}) }),
      domainProvenance: {
        ...(current.domainProvenance || { conflict: 'default_v2' }),
        ...(isPlainObject(patch?.domainProvenance) ? patch.domainProvenance : {}),
        ...(conflictExplicitlyPatched && !isPlainObject(patch?.domainProvenance) ? { conflict: 'user' } : {}),
      },
      analysisModules: {
        ...current.analysisModules,
        ...(isPlainObject(patch?.analysisModules) ? patch.analysisModules : {}),
        keyMetadata: { ...(current.analysisModules?.keyMetadata || {}), ...(isPlainObject(patch?.analysisModules?.keyMetadata) ? patch.analysisModules.keyMetadata : {}) },
      },
      rosterDiscovery: normalizeRosterDiscovery({ ...current.rosterDiscovery, ...(isPlainObject(patch?.rosterDiscovery) ? patch.rosterDiscovery : {}) }),
      loreSelection: normalizeLoreSelection({ ...current.loreSelection, ...(isPlainObject(patch?.loreSelection) ? patch.loreSelection : {}) }),
      updatedAt: new Date().toISOString(),
    };
    const previousSelection = JSON.stringify(current.analysisModules || {});
    const previousLoreSelection = JSON.stringify(current.loreSelection || normalizeLoreSelection(null));
    const saved = await saveBotOverrides(store);
    if (JSON.stringify(saved.bots?.[sourceBundleKey]?.analysisModules || {}) !== previousSelection) moduleSelectionGenerations.set(sourceBundleKey, mapGeneration(moduleSelectionGenerations, sourceBundleKey) + 1);
    if (JSON.stringify(saved.bots?.[sourceBundleKey]?.loreSelection || normalizeLoreSelection(null)) !== previousLoreSelection) loreSelectionGenerations.set(sourceBundleKey, mapGeneration(loreSelectionGenerations, sourceBundleKey) + 1);
    return saved;
  }

  

  function scopeCatalogSummary(scope, state = null, extra = {}) {
    const goals = Object.values(state?.goals || {}).filter((goal) => !['complete', 'abandon'].includes(goal?.status));
    return {
      sourceBundleKey: scope.sourceBundleKey,
      characterId: String(scope.identity?.id || ''),
      characterName: truncate(scope.identity?.name || scope.sourceBundleKey, 200),
      scopeKey: scope.scopeKey,
      chatId: String(scope.chatId || scope.chat?.id || scope.chat?.chatId || ''),
      chatName: truncate(scope.chatName || scope.chat?.name || `채팅 ${Number(scope.chatIndex || 0) + 1}`, 220),
      characterIndex: Number.isInteger(scope.characterIndex) ? scope.characterIndex : -1,
      chatIndex: Number.isInteger(scope.chatIndex) ? scope.chatIndex : -1,
      lastUpdatedAt: state?.updatedAt || null,
      turnIndex: Number(state?.turnIndex || 0),
      eventCount: Array.isArray(state?.events) ? state.events.length : 0,
      interactionCount: Array.isArray(state?.interactionHistory) ? state.interactionHistory.length : 0,
      activeGoalCount: goals.length,
      mobCount: clampInt(extra.mobCount, 0, 0, 1000000),
      profileCount: clampInt(extra.profileCount, 0, 0, 100000),
      // Deprecated metadata has no consumer. Preserve old saved values without
      // rebuilding a new unused list on every commit.
      ...(Object.prototype.hasOwnProperty.call(state?.scopeMeta || {}, 'observedIds') ? { observedIds: safeClone(state.scopeMeta.observedIds) } : {}),
      variantKey: String(state?.variantKey || scope.variantKey || 'default'),
      variantLabel: truncate(scope.variantLabel || '', 160),
      variantSignature: String(scope.variantSignature || ''),
      sourceHash: String(scope.sourceHash || ''),
    };
  }

  function scrubCatalogForStaleFence(catalog, fence) {
    const next = normalizeScopeCatalog(catalog);
    if (fence?.allResetGeneration !== allResetGeneration) return emptyScopeCatalog();
    if (fence?.sourceBundleKey && fence.botResetGeneration !== mapGeneration(botResetGenerations, fence.sourceBundleKey)) {
      delete next.bots[fence.sourceBundleKey];
      return next;
    }
    if (fence?.sourceBundleKey && fence?.scopeKey && fence.scopeResetGeneration !== mapGeneration(scopeResetGenerations, fence.scopeKey)) {
      const bot = next.bots[fence.sourceBundleKey];
      if (bot?.chats) {
        delete bot.chats[fence.scopeKey];
        bot.lastScopeKey = Object.values(bot.chats).sort((left, right) => String(right.lastUpdatedAt || '').localeCompare(String(left.lastUpdatedAt || '')))[0]?.scopeKey || '';
      }
    }
    return next;
  }

  function upsertScopeCatalog(scope, state = null, extra = {}, fence = null) {
    if (!scope?.sourceBundleKey) return Promise.resolve(null);
    scopeCatalogWriteQueue = scopeCatalogWriteQueue.catch(() => {}).then(async () => {
      if (fence) assertBackgroundFence(fence, 'scope catalog update start');
      const catalog = await loadScopeCatalog();
      if (fence) assertBackgroundFence(fence, 'scope catalog update read');
      const summary = scopeCatalogSummary(scope, state, extra);
      const existing = catalog.bots[scope.sourceBundleKey] || { chats: {} };
      const existingSignature = JSON.stringify(existing);
      const updatedAt = summary.lastUpdatedAt || existing.lastSeenAt || new Date().toISOString();
      const bot = {
        ...existing,
        sourceBundleKey: scope.sourceBundleKey,
        characterId: summary.characterId || existing.characterId || '',
        characterName: summary.characterName || existing.characterName || scope.sourceBundleKey,
        lastScopeKey: summary.scopeKey || existing.lastScopeKey || '',
        lastSeenAt: updatedAt,
        profileCount: summary.profileCount > 0 ? summary.profileCount : Number(existing.profileCount || 0),
        chats: isPlainObject(existing.chats) ? { ...existing.chats } : {},
      };
      if (summary.scopeKey) {
        bot.chats[summary.scopeKey] = {
          ...(bot.chats[summary.scopeKey] || {}),
          scopeKey: summary.scopeKey,
          sourceBundleKey: scope.sourceBundleKey,
          chatId: summary.chatId,
          chatName: summary.chatName,
          characterIndex: summary.characterIndex,
          chatIndex: summary.chatIndex,
          lastUpdatedAt: updatedAt,
          turnIndex: summary.turnIndex,
          eventCount: summary.eventCount,
          interactionCount: summary.interactionCount,
          activeGoalCount: summary.activeGoalCount,
          mobCount: summary.mobCount,
          variantKey: summary.variantKey,
          variantLabel: summary.variantLabel,
          variantSignature: summary.variantSignature,
          sourceHash: summary.sourceHash,
        };
      }
      if (JSON.stringify(bot) === existingSignature) return catalog;
      catalog.bots[scope.sourceBundleKey] = bot;
      if (fence) assertBackgroundFence(fence, 'scope catalog update write');
      const saved = await saveScopeCatalog(catalog);
      if (fence && !backgroundFenceIsCurrent(fence)) {
        if (backgroundFenceResetInvalidated(fence)) {
          const cleaned = scrubCatalogForStaleFence(saved, fence);
          await saveScopeCatalog(cleaned);
        }
        throw staleLifecycleError('scope catalog update completion');
      }
      return saved;
    });
    return scopeCatalogWriteQueue;
  }

  function ensureProfileBundlesInCatalog(catalog, profileStore) {
    let changed = false;
    for (const [bundleKey, bundle] of Object.entries(profileStore?.sourceBundles || {})) {
      if (!catalog.bots[bundleKey]) {
        catalog.bots[bundleKey] = {
          sourceBundleKey: bundleKey,
          characterId: String(bundle?.identity?.id || ''),
          characterName: truncate(bundle?.identity?.name || bundleKey, 200),
          lastScopeKey: '',
          lastSeenAt: bundle?.compiledAt || null,
          profileCount: Array.isArray(bundle?.characterIds) ? bundle.characterIds.length : 0,
          chats: {},
        };
        changed = true;
      } else {
        const bot = catalog.bots[bundleKey];
        const nextName = truncate(bundle?.identity?.name || bot.characterName || bundleKey, 200);
        const nextCount = Array.isArray(bundle?.characterIds) ? bundle.characterIds.length : bot.profileCount || 0;
        if (bot.characterName !== nextName || bot.profileCount !== nextCount) {
          bot.characterName = nextName;
          bot.characterId = String(bundle?.identity?.id || bot.characterId || '');
          bot.profileCount = nextCount;
          changed = true;
        }
      }
    }
    return changed;
  }

  function parseJsonRecord(text, fallback = {}) {
    const value = String(text || '').trim();
    if (!value) return { ...fallback };
    const parsed = JSON.parse(value);
    if (!isPlainObject(parsed)) throw new Error('JSON value must be an object');
    return parsed;
  }

  function withTimeout(promise, timeoutMs, label) {
    let timer = null;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error(`${label} timed out after ${Math.round(timeoutMs / 1000)}s`)), timeoutMs);
    });
    return Promise.race([promise, timeout]).finally(() => { if (timer) clearTimeout(timer); });
  }

  function createRequestGuard(timeoutMs = MAIN_REQUEST_DEADLINE_MS, label = 'beforeRequest') {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const listeners = new Set();
    let deadlineAt = Date.now() + Math.max(1, timeoutMs);
    let stopped = false;
    let stopReason = null;
    let timer = null;
    const makeDeadlineError = (stage = label) => {
      const error = new Error(`${stage} exceeded the ${Math.round(timeoutMs / 1000)}s main-request safety deadline`);
      error.code = 'EROSYNC_MAIN_REQUEST_DEADLINE';
      return error;
    };
    const guard = {
      signal: controller?.signal || null,
      get deadlineAt() { return deadlineAt; },
      // 긴급 판단처럼 메인 요청이 일부러 더 기다릴 때만: 시한을 지금부터 ms 뒤까지 늘린다(줄이지는 않음)
      extend(ms) {
        if (stopped) return;
        const until = Date.now() + Math.max(0, Number(ms) || 0);
        if (until <= deadlineAt) return;
        deadlineAt = until;
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => guard.abort(makeDeadlineError()), Math.max(1, deadlineAt - Date.now()));
      },
      get aborted() { return stopped || controller?.signal?.aborted === true; },
      remainingMs() { return Math.max(0, deadlineAt - Date.now()); },
      abort(reason = makeDeadlineError()) {
        if (stopped) return;
        stopped = true;
        stopReason = reason instanceof Error ? reason : makeDeadlineError();
        try { controller?.abort(stopReason); } catch (_) { try { controller?.abort(); } catch (_) {} }
        for (const reject of [...listeners]) reject(stopReason);
        listeners.clear();
      },
      throwIfAborted(stage = label) {
        if (!stopped && Date.now() >= deadlineAt) guard.abort(makeDeadlineError(stage));
        if (stopped || controller?.signal?.aborted) throw stopReason || makeDeadlineError(stage);
      },
      wait(promise, stage = label) {
        const pending = Promise.resolve(promise);
        try { guard.throwIfAborted(stage); }
        catch (error) { pending.catch(() => {}); throw error; }
        return new Promise((resolve, reject) => {
          let settled = false;
          const rejectOnAbort = (reason) => {
            if (settled) return;
            settled = true;
            listeners.delete(rejectOnAbort);
            reject(reason || stopReason || makeDeadlineError(stage));
          };
          listeners.add(rejectOnAbort);
          pending.then((value) => {
            if (settled) return;
            listeners.delete(rejectOnAbort);
            try {
              guard.throwIfAborted(stage);
              settled = true;
              resolve(value);
            } catch (error) {
              settled = true;
              reject(error);
            }
          }, (error) => {
            if (settled) return;
            settled = true;
            listeners.delete(rejectOnAbort);
            reject(error);
          });
        });
      },
      dispose() {
        transferRequestGuards.delete(guard);
        if (timer) clearTimeout(timer);
        timer = null;
      },
    };
    timer = setTimeout(() => guard.abort(makeDeadlineError()), Math.max(1, timeoutMs));
    transferRequestGuards.add(guard);
    return guard;
  }

  function extractJsonObject(text) {
    const source = String(text || '').trim();
    if (!source) throw new Error('empty JSON response');
    const candidates = [source];
    for (const match of source.matchAll(/```(?:json)?\s*([\s\S]*?)```/gi)) candidates.push(match[1].trim());
    for (let start = 0; start < source.length; start += 1) {
      if (source[start] !== '{') continue;
      let depth = 0;
      let inString = false;
      let escaped = false;
      for (let index = start; index < source.length; index += 1) {
        const character = source[index];
        if (inString) {
          if (escaped) escaped = false;
          else if (character === '\\') escaped = true;
          else if (character === '"') inString = false;
          continue;
        }
        if (character === '"') inString = true;
        else if (character === '{') depth += 1;
        else if (character === '}') {
          depth -= 1;
          if (depth === 0) {
            candidates.push(source.slice(start, index + 1));
            start = index;
            break;
          }
        }
      }
    }
    let lastError = null;
    for (const candidate of candidates) {
      try {
        const parsed = JSON.parse(candidate);
        if (isPlainObject(parsed)) return parsed;
      } catch (error) { lastError = error; }
    }
    throw new Error(`invalid JSON response: ${lastError?.message || 'no object found'}`);
  }

  function extractOpenAIChatText(data) {
    const content = data?.choices?.[0]?.message?.content;
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) {
      return content.map((part) => typeof part === 'string' ? part : part?.text || '').join('');
    }
    return '';
  }

  function extractOpenAIResponsesText(data) {
    if (typeof data?.output_text === 'string') return data.output_text;
    const texts = [];
    for (const output of Array.isArray(data?.output) ? data.output : []) {
      for (const part of Array.isArray(output?.content) ? output.content : []) {
        if (typeof part?.text === 'string') texts.push(part.text);
      }
    }
    return texts.join('');
  }

  function extractClaudeText(data) {
    return (Array.isArray(data?.content) ? data.content : [])
      .filter((part) => part?.type === 'text' && typeof part.text === 'string')
      .map((part) => part.text)
      .join('');
  }

  function extractGeminiText(data) {
    return (Array.isArray(data?.candidates) ? data.candidates : [])
      .flatMap((candidate) => Array.isArray(candidate?.content?.parts) ? candidate.content.parts : [])
      .map((part) => typeof part?.text === 'string' ? part.text : '')
      .join('');
  }

  // The reason a provider gives with a refusal, for the status line. OpenCode Go explains its refusals this way.
  function providerErrorDetail(text) {
    let data = null;
    try { data = JSON.parse(text); } catch (_) {}
    const raw = data ? data.error?.message || data.message || (typeof data.error === 'string' ? data.error : '') : String(text || '').trim().startsWith('<') ? '' : text;
    const detail = truncate(String(raw || '').replace(/\s+/g, ' ').trim(), 300);
    return detail ? ` · ${detail}` : '';
  }

  async function nativeJsonRequest(url, options, timeoutSeconds, label, requestGuard = null, detailErrors = false) {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const linkedSignals = [options?.signal, requestGuard?.signal].filter((signal, index, list) => signal && list.indexOf(signal) === index);
    const abortLinks = [];
    let providerTimedOut = false;
    const timeoutMs = Math.max(1, Number(timeoutSeconds || 0) * 1000);
    const deadlineAt = Date.now() + timeoutMs;
    const timeoutError = () => {
      const error = new Error(`${label} timed out after ${timeoutSeconds}s`);
      error.code = 'EROSYNC_PROVIDER_TIMEOUT';
      return error;
    };
    const abortForTimeout = () => {
      providerTimedOut = true;
      try { controller?.abort(timeoutError()); } catch (_) { try { controller?.abort(); } catch (_) {} }
    };
    const waitWithinDeadline = async (promise, stage) => {
      // The provider promise already exists even when the deadline just expired.
      Promise.resolve(promise).catch(() => {});
      requestGuard?.throwIfAborted(stage);
      const remainingMs = Math.max(0, deadlineAt - Date.now());
      if (remainingMs <= 0) {
        abortForTimeout();
        throw timeoutError();
      }
      const guarded = requestGuard ? requestGuard.wait(Promise.resolve(promise), stage) : Promise.resolve(promise);
      try {
        return await withTimeout(guarded, remainingMs, `${label} deadline`);
      } catch (error) {
        if (Date.now() >= deadlineAt || String(error?.message || '').includes(`${label} deadline timed out`)) {
          abortForTimeout();
          throw timeoutError();
        }
        throw error;
      }
    };
    if (controller) {
      for (const signal of linkedSignals) {
        const abort = () => {
          try { controller.abort(signal.reason); } catch (_) { try { controller.abort(); } catch (_) {} }
        };
        if (signal.aborted) abort();
        else {
          signal.addEventListener('abort', abort, { once: true });
          abortLinks.push([signal, abort]);
        }
      }
    }
    try {
      requestGuard?.throwIfAborted(label);
      const fetchOptions = { ...options, ...(controller ? { signal: controller.signal } : linkedSignals[0] ? { signal: linkedSignals[0] } : {}) };
      const fetchPromise = R.nativeFetch(url, fetchOptions);
      const response = await waitWithinDeadline(fetchPromise, label);
      const textPromise = response.text();
      const text = await waitWithinDeadline(textPromise, `${label} response`);
      if (response.status < 200 || response.status >= 300) throw providerHttpError(label, response, text, detailErrors);
      try { return JSON.parse(text); } catch (error) {
        const failure = new Error(`${label} returned invalid JSON`);
        failure.code = 'EROSYNC_PROVIDER_RESPONSE_JSON';
        throw failure;
      }
    } catch (error) {
      requestGuard?.throwIfAborted(label);
      if (providerTimedOut) throw timeoutError();
      throw error;
    } finally {
      for (const [signal, abort] of abortLinks) signal.removeEventListener('abort', abort);
    }
  }


  // 흘려받기(2026-10-13): 오래 생각하는 모델은 답을 다 만들 때까지 연결이 조용해서, 중간 장치가 60초 무응답으로 끊었다(HTTP 504).
  // 흘려받으면 생각·글 조각이 계속 와서 연결이 살아 있다. 흘려받는 동안 "타임아웃(초)"은 아무것도 오지 않는 시간의 한도이고,
  // 조각이 계속 오면 요청 한 번에 PROVIDER_STREAM_CAP_MS까지 기다린다.
  const PROVIDER_STREAM_CAP_MS = 600000;

  function providerStreams(providerId, profile) {
    return providerId !== 'risu' && providerId !== 'vertex' && !['vertex', 'gemini'].includes(profile?.apiFormat);
  }

  // 요청 한 번에 허용하는 시간: 흘려받는 제공자는 상한, 아니면 "타임아웃(초)" 그대로.
  function providerAttemptLimitMs(assignment) {
    const timeoutMs = clampInt(assignment?.profile?.timeoutSeconds, 120, 15, 600) * 1000;
    return providerStreams(assignment?.providerId, assignment?.profile) ? Math.max(timeoutMs, PROVIDER_STREAM_CAP_MS) : timeoutMs;
  }

  // 실패한 응답을 누가 보냈는지: server 머리글, 오류 페이지 제목, 또는 JSON 오류 문구. 키처럼 보이는 글자는 지운다.
  function providerFailureSource(response, text) {
    const clean = value => truncate(String(value || '').replace(/[\u0000-\u001f\u007f]+/g, ' ')
      .replace(/\b(?:sk|pk|rk|oc|key|token|bearer)[-_:][^\s,;]*/gi, '…').replace(/[\w\-.*~+/=]{24,}/g, '…').replace(/\s+/g, ' ').trim(), 80);
    let server = '';
    try { server = clean(response?.headers?.get?.('server')); } catch (_) {}
    const body = String(text || '').trim();
    const title = clean(/<title[^>]*>([\s\S]*?)<\/title>/i.exec(body)?.[1]);
    const note = title || !body.startsWith('{') ? '' : clean(providerErrorDetail(body).replace(/^ · /, ''));
    return { server, title, text: truncate([server && `server ${server}`, title || note].filter(Boolean).join(' · '), 120) };
  }

  function providerHttpError(label, response, text, detailErrors = false) {
    const source = providerFailureSource(response, text);
    // Gemini·Vertex(2026-10-15): 앞단 HTML 오류(제목·server 머리글뿐인 400)면 주소 확인을 덧붙이고, JSON 오류면 error.message 첫 줄을 보인다
    const google = /^(?:Vertex AI|Custom Gemini)$/.test(String(label || ''));
    const body = String(text || '').trim();
    const front = google && (body.startsWith('<') || !!source.title) ? ' · 구글 앞단에서 거부(주소 확인)' : '';
    const line = google && !front && !detailErrors ? providerJsonErrorLine(body) : '';
    const error = new Error(`${label} HTTP ${response.status}${detailErrors ? providerErrorDetail(text) : ''}${line ? ` · ${line}` : ''}${source.server ? ` · server ${source.server}` : ''}${source.title ? ` · ${source.title}` : ''}${front}`);
    error.code = 'EROSYNC_PROVIDER_HTTP';
    error.status = response.status;
    if (source.text) error.source = source.text;
    return error;
  }

  // JSON 오류의 error.message 첫 줄(배열로 오는 Vertex 오류도). 키처럼 보이는 글자는 지운다.
  function providerJsonErrorLine(body) {
    let data = null;
    try { data = JSON.parse(body); } catch (_) { return ''; }
    if (Array.isArray(data)) data = data[0];
    const raw = data?.error?.message || data?.message || (typeof data?.error === 'string' ? data.error : '');
    return truncate(String(raw || '').split('\n')[0].replace(/\b(?:sk|pk|rk|oc|key|token|bearer)[-_:][^\s,;]*/gi, '…').trim(), 200);
  }

  // 흐름 안에서 온 오류 조각. 상태 번호가 있으면 HTTP 오류처럼(5xx는 재요청 대상), 없으면 문구로 나눈다.
  function providerStreamError(label, value, detailErrors = false) {
    const data = isPlainObject(value) ? value : { message: String(value || '') };
    const message = String(data.message || data.error?.message || (typeof data.error === 'string' ? data.error : '') || data.type || 'stream error').replace(/\s+/g, ' ').trim();
    const numbered = [data.status, data.code, data.error?.code, /\[(\d{3})\]/.exec(message)?.[1]].map(Number).find(number => number >= 400 && number <= 599) || 0;
    const status = numbered || (/overloaded/i.test(`${data.type || ''} ${message}`) ? 503 : 0);
    const error = new Error(`${label} stream error${status ? ` ${status}` : ''}${detailErrors && message ? ` · ${truncate(message, 300)}` : ''}`);
    error.code = status ? 'EROSYNC_PROVIDER_HTTP' : /timed? ?out|timeout/i.test(message) ? 'EROSYNC_PROVIDER_TIMEOUT' : 'EROSYNC_PROVIDER_FAILED';
    if (status) error.status = status;
    error.source = truncate(`stream · ${providerFailureSource(null, JSON.stringify({ error: { message } })).text || 'error'}`, 120);
    return error;
  }

  // 흘려받은 글을 형식마다 모아, 한 번에 받았을 때와 같은 모양의 응답으로 돌려준다(생각 조각은 답에 넣지 않음).
  // 서버가 흘려보내지 않고 JSON 하나를 주면 그 JSON을 그대로 돌려준다.
  function providerStreamCollector(format, contentType, label, detailErrors = false) {
    let mode = /event-stream/.test(contentType) ? 'sse' : /ndjson|jsonl/.test(contentType) ? 'ndjson' : /json/.test(contentType) ? 'whole' : '';
    let head = '', whole = '', buffer = '', eventName = '', dataLines = [];
    let text = '', finish = '', model = '', usage = null, completed = null, received = false;
    const fail = value => { throw providerStreamError(label, value, detailErrors); };
    const take = (data, name = '') => {
      if (!isPlainObject(data)) return;
      received = true;
      const type = String(data.type || name || '');
      if (format === 'ollama_chat') {
        if (data.error) fail(data.error);
        if (typeof data.message?.content === 'string') text += data.message.content;
        else if (typeof data.response === 'string') text += data.response;
        if (data.done) finish = String(data.done_reason || 'stop');
      } else if (format === 'claude') {
        if (type === 'error' || data.error) fail(data.error || data);
        if (type === 'content_block_delta' && data.delta?.type === 'text_delta') text += String(data.delta.text || '');
        else if (type === 'content_block_start' && data.content_block?.type === 'text') text += String(data.content_block.text || '');
        else if (type === 'message_delta' && data.delta?.stop_reason) finish = String(data.delta.stop_reason);
        else if (type === 'message_start' && data.message?.model) model = String(data.message.model);
      } else if (format === 'openai_responses') {
        if (type === 'error') fail(data.error || data);
        if (type === 'response.failed') fail(data.response?.error || { message: 'response failed' });
        if (type === 'response.output_text.delta') text += String(data.delta || '');
        else if (type === 'response.completed' || type === 'response.incomplete') completed = isPlainObject(data.response) ? data.response : completed;
      } else {
        if (data.error) fail(data.error);
        const choice = Array.isArray(data.choices) ? data.choices[0] : null;
        const delta = choice?.delta?.content;
        if (typeof delta === 'string') text += delta;
        else if (Array.isArray(delta)) text += delta.map(part => typeof part === 'string' ? part : part?.text || '').join('');
        else if (!text && typeof choice?.message?.content === 'string') text = choice.message.content;
        if (choice?.finish_reason) finish = String(choice.finish_reason);
        if (data.model) model = String(data.model);
      }
      if (isPlainObject(data.usage)) usage = data.usage;
    };
    const dispatch = () => {
      const payload = dataLines.join('\n');
      const name = eventName;
      dataLines = []; eventName = '';
      if (!payload || payload.trim() === '[DONE]') return;
      let data = null;
      try { data = JSON.parse(payload); } catch (_) { return; }
      take(data, name);
    };
    const sseLine = line => {
      if (line === '') return dispatch();
      if (line[0] === ':') return;
      const colon = line.indexOf(':');
      const field = colon < 0 ? line : line.slice(0, colon);
      const value = colon < 0 ? '' : line.slice(colon + 1).replace(/^ /, '');
      if (field === 'data') dataLines.push(value);
      else if (field === 'event') eventName = value;
    };
    const ndjsonLine = line => {
      if (!line.trim()) return;
      let data = null;
      try { data = JSON.parse(line); } catch (_) { whole += `${line}\n`; return; }
      take(data);
    };
    const feed = (chunk, final = false) => {
      buffer += chunk;
      const lines = buffer.split(/\r?\n/);
      buffer = final ? '' : lines.pop();
      for (const line of lines) (mode === 'sse' ? sseLine : ndjsonLine)(line);
      if (final && mode === 'sse') dispatch();
    };
    const result = () => {
      if (format === 'ollama_chat') return { message: { role: 'assistant', content: text }, done: true, ...(finish ? { done_reason: finish } : {}) };
      if (format === 'claude') return { type: 'message', role: 'assistant', ...(model ? { model } : {}), content: [{ type: 'text', text }], stop_reason: finish || null, ...(usage ? { usage } : {}) };
      if (format === 'openai_responses') return completed && (extractOpenAIResponsesText(completed) || !text) ? completed : { ...(completed || {}), output_text: text };
      return { ...(model ? { model } : {}), choices: [{ index: 0, message: { role: 'assistant', content: text }, finish_reason: finish || null }], ...(usage ? { usage } : {}) };
    };
    return {
      push(chunk) {
        if (!chunk) return;
        if (!mode) {
          head += chunk;
          const start = head.trimStart();
          if (!start) return;
          mode = /^(?:data|event|id|retry)\s*:|^:/.test(start) ? 'sse' : format === 'ollama_chat' ? 'ndjson' : 'whole';
          chunk = head; head = '';
        }
        if (mode === 'whole') whole += chunk;
        else feed(chunk);
      },
      finish() {
        if (!mode) { mode = 'whole'; whole = head; }
        if (mode === 'whole') {
          const body = whole.trim();
          try { return JSON.parse(body); } catch (_) {}
          // 머리말 없이 흘려보낸 글
          whole = '';
          mode = /^(?:data|event)\s*:/m.test(body) ? 'sse' : 'ndjson';
          feed(body, true);
        } else feed('', true);
        if (!received) {
          const rest = whole.trim();
          if (rest) { try { return JSON.parse(rest); } catch (_) {} }
          const failure = new Error(`${label} returned invalid JSON`);
          failure.code = 'EROSYNC_PROVIDER_RESPONSE_JSON';
          throw failure;
        }
        return result();
      },
    };
  }

  // nativeJsonRequest의 흘려받기 판. 조각이 하나 올 때마다 무응답 시계를 다시 잰다.
  async function nativeStreamRequest(url, options, timeoutSeconds, label, requestGuard = null, detailErrors = false, format = 'openai_chat') {
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    const linkedSignals = [options?.signal, requestGuard?.signal].filter((signal, index, list) => signal && list.indexOf(signal) === index);
    const abortLinks = [];
    const idleMs = Math.max(1, Number(timeoutSeconds || 0) * 1000);
    const capAt = Date.now() + PROVIDER_STREAM_CAP_MS;
    let idleAt = Date.now() + idleMs;
    let expired = '';
    const timeoutError = () => {
      const error = new Error(expired === 'cap'
        ? `${label} stream exceeded ${Math.round(PROVIDER_STREAM_CAP_MS / 1000)}s`
        : `${label} timed out after ${timeoutSeconds}s without data`);
      error.code = 'EROSYNC_PROVIDER_TIMEOUT';
      return error;
    };
    const expire = () => {
      expired = capAt <= idleAt ? 'cap' : 'idle';
      try { controller?.abort(timeoutError()); } catch (_) { try { controller?.abort(); } catch (_) {} }
    };
    const waitAlive = async (promise, stage) => {
      Promise.resolve(promise).catch(() => {});
      requestGuard?.throwIfAborted(stage);
      const until = Math.min(idleAt, capAt);
      const remainingMs = until - Date.now();
      if (remainingMs <= 0) { expire(); throw timeoutError(); }
      const guarded = requestGuard ? requestGuard.wait(Promise.resolve(promise), stage) : Promise.resolve(promise);
      try {
        return await withTimeout(guarded, remainingMs, `${label} stream`);
      } catch (error) {
        if (Date.now() >= until || String(error?.message || '').includes(`${label} stream timed out`)) { expire(); throw timeoutError(); }
        throw error;
      }
    };
    if (controller) {
      for (const signal of linkedSignals) {
        const abort = () => {
          try { controller.abort(signal.reason); } catch (_) { try { controller.abort(); } catch (_) {} }
        };
        if (signal.aborted) abort();
        else {
          signal.addEventListener('abort', abort, { once: true });
          abortLinks.push([signal, abort]);
        }
      }
    }
    let reader = null;
    try {
      requestGuard?.throwIfAborted(label);
      const fetchOptions = { ...options, ...(controller ? { signal: controller.signal } : linkedSignals[0] ? { signal: linkedSignals[0] } : {}) };
      const response = await waitAlive(R.nativeFetch(url, fetchOptions), label);
      idleAt = Date.now() + idleMs;
      if (response.status < 200 || response.status >= 300) throw providerHttpError(label, response, await waitAlive(response.text(), `${label} response`), detailErrors);
      let contentType = '';
      try { contentType = String(response.headers?.get?.('content-type') || '').toLowerCase(); } catch (_) {}
      const collector = providerStreamCollector(format, contentType, label, detailErrors);
      reader = typeof response.body?.getReader === 'function' ? response.body.getReader() : null;
      if (!reader) {
        collector.push(String(await waitAlive(response.text(), `${label} response`) ?? ''));
        return collector.finish();
      }
      const decoder = new TextDecoder();
      for (;;) {
        const { value, done } = await waitAlive(reader.read(), `${label} stream`);
        if (done) break;
        idleAt = Date.now() + idleMs;
        collector.push(typeof value === 'string' ? value : decoder.decode(value, { stream: true }));
      }
      reader = null;
      collector.push(decoder.decode());
      return collector.finish();
    } catch (error) {
      requestGuard?.throwIfAborted(label);
      if (expired) throw timeoutError();
      throw error;
    } finally {
      if (reader) { try { Promise.resolve(reader.cancel()).catch(() => {}); } catch (_) {} }
      for (const [signal, abort] of abortLinks) signal.removeEventListener('abort', abort);
    }
  }

  function buildCommonBody(profile, messages) {
    const body = {
      model: profile.model,
      messages,
    };
    const temperature = optionalNumber(profile.temperature);
    if (temperature !== null) body.temperature = temperature;
    if (profile.maxTokens > 0) body.max_completion_tokens = profile.maxTokens;
    if (profile.reasoningEffort) body.reasoning_effort = profile.reasoningEffort;
    return body;
  }

  function applyExtraBody(profile, body) {
    const extra = parseJsonRecord(profile.extraBodyJson, {});
    return { ...body, ...extra };
  }

  function buildBearerHeaders(profile, extra = {}) {
    const headers = {
      'Content-Type': 'application/json',
      ...extra,
      ...parseJsonRecord(profile.extraHeadersJson, {}),
    };
    if (profile.apiKey) headers.Authorization = `Bearer ${profile.apiKey}`;
    return headers;
  }

  function risuProviderBusyError(executionRole, activeRoles, code = 'EROSYNC_RISU_PROVIDER_BUSY') {
    const error = new Error(`RisuAI auxiliary provider is busy (${activeRoles.join(', ') || 'unknown'}); ${executionRole} was skipped`);
    error.code = code;
    error.executionRole = executionRole;
    error.activeRoles = activeRoles;
    return error;
  }

  function preemptActiveBehindForDirector() {
    for (const entry of risuActiveCalls.values()) {
      if (entry.executionRole !== 'behind') continue;
      entry.preempt?.('director look-ahead has priority over Behind');
    }
  }

  function preemptAllActiveRisuCalls(reason = 'Erosync auxiliary provider lifecycle ended') {
    for (const entry of risuActiveCalls.values()) entry.preempt?.(reason);
  }

  function activeRisuRoles() {
    return [...risuActiveCalls.values()].map((entry) => `${entry.executionRole}${entry.preempted ? ':orphan' : ''}`);
  }

  async function runRisuProvider(messages, profile, config, requestGuard = null, executionRole = 'director') {
    if (typeof R.runLLMModel !== 'function') throw new Error('runLLMModel is unavailable');
    const operationalRole = ['director', 'profile', 'behind'].includes(executionRole) ? executionRole : 'director';
    const activeEntries = [...risuActiveCalls.values()];
    if (operationalRole === 'director') {
      const nonBehind = activeEntries.filter((entry) => entry.executionRole !== 'behind');
      if (nonBehind.length > 0) throw risuProviderBusyError(operationalRole, activeRisuRoles());
      preemptActiveBehindForDirector();
    } else if (activeEntries.length > 0) {
      const code = operationalRole === 'behind' ? 'EROSYNC_BEHIND_SKIPPED_BUSY' : 'EROSYNC_RISU_PROVIDER_BUSY';
      throw risuProviderBusyError(operationalRole, activeRisuRoles(), code);
    }
    if (String(profile.model || '').startsWith('pluginmodel:::') && config.risuAllowPluginModels !== true) {
      throw new Error('플러그인 제공 보조 모델은 현재 차단되어 있습니다. AI 연결에서 플러그인 모델 허용을 켜거나 Erosync 직접 제공자를 사용하세요.');
    }
    const options = { mode: 'otherAx', messages, allowPlugins: config.risuAllowPluginModels === true };
    if (profile.model) options.staticModel = profile.model;
    requestGuard?.throwIfAborted('RisuAI model');
    const callId = `risu_${++risuActiveCallSequence}`;
    let rejectPreempt = null;
    const preemptPromise = new Promise((_, reject) => { rejectPreempt = reject; });
    const activeCall = {
      id: callId,
      executionRole: operationalRole,
      lifecycleEpoch,
      startedAt: Date.now(),
      preempted: false,
      preempt(reason = 'preempted') {
        if (activeCall.preempted) return;
        activeCall.preempted = true;
        const error = new Error(reason);
        error.code = 'EROSYNC_RISU_PREEMPTED';
        error.executionRole = operationalRole;
        rejectPreempt?.(error);
      },
    };
    risuActiveCalls.set(callId, activeCall);
    const releaseCall = () => {
      if (risuActiveCalls.get(callId) === activeCall) risuActiveCalls.delete(callId);
    };
    let underlyingPromise;
    try {
      underlyingPromise = Promise.resolve(R.runLLMModel(options));
    } catch (error) {
      releaseCall();
      throw error;
    }
    const settledPromise = underlyingPromise.then(
      (value) => { releaseCall(); return value; },
      (error) => { releaseCall(); throw error; },
    );
    const providerPromise = Promise.race([
      withTimeout(settledPromise, profile.timeoutSeconds * 1000, 'RisuAI model'),
      preemptPromise,
    ]);
    const response = requestGuard ? await requestGuard.wait(providerPromise, 'RisuAI model') : await providerPromise;
    requestGuard?.throwIfAborted('RisuAI model');
    if (unloaded || activeCall.lifecycleEpoch !== lifecycleEpoch) {
      const error = new Error('stale RisuAI auxiliary provider result discarded after lifecycle invalidation');
      error.code = 'EROSYNC_STALE_PROVIDER_RESULT';
      error.executionRole = operationalRole;
      throw error;
    }
    if (typeof response === 'string') return response;
    if (response?.type === 'fail') throw new Error(truncate(response.result || 'RisuAI model failed', 700));
    if (response?.type === 'success') return String(response.result || '');
    if (response?.type === 'multiline' && Array.isArray(response.result)) {
      return response.result.map((entry) => Array.isArray(entry) ? String(entry[1] || '') : '').join('\n');
    }
    throw new Error(`unsupported RisuAI model response: ${String(response?.type || typeof response)}`);
  }

  async function runOllamaCloudProvider(messages, profile, requestGuard = null) {
    if (!profile.model) throw new Error('Ollama Cloud model is empty');
    if (!profile.apiKey) throw new Error('Ollama Cloud API key is empty');
    const body = {
      model: profile.model,
      messages: messages.map((message) => ({ role: message.role, content: String(message.content || '') })),
      stream: true,
    };
    if (profile.temperature !== '' && profile.temperature !== null && profile.temperature !== undefined) {
      body.options = { temperature: clampNumber(profile.temperature, 0.7, 0, 2) };
    }
    const data = await nativeStreamRequest(profile.endpoint || 'https://ollama.com/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${profile.apiKey}`,
        ...parseJsonRecord(profile.extraHeadersJson, {}),
      },
      body: JSON.stringify(applyExtraBody(profile, body)),
    }, profile.timeoutSeconds, 'Ollama Cloud', requestGuard, false, 'ollama_chat');
    const text = String(data?.message?.content || data?.response || '');
    if (!text.trim()) throw new Error('Ollama Cloud returned empty content');
    return text;
  }

  async function runOpenAIChatProvider(messages, profile, providerId, requestGuard = null) {
    if (!profile.endpoint) throw new Error(`${providerId} endpoint is empty`);
    if (!profile.model) throw new Error(`${providerId} model is empty`);
    let body = buildCommonBody(profile, messages);
    if (body.max_completion_tokens) {
      body.max_tokens = body.max_completion_tokens;
      delete body.max_completion_tokens;
    }
    body.stream = true;
    body = applyExtraBody(profile, body);
    if (messages.webSearch === true && providerSearchTool(providerId, profile)?.kind === 'openrouter') body.plugins = [...(Array.isArray(body.plugins) ? body.plugins : []), { id: 'web' }]; // 웹 검색(2026-10-15)
    const additional = openCodeGoHeaders(providerId);
    if (providerId === 'openrouter') {
      if (profile.openRouterReferer) additional['HTTP-Referer'] = profile.openRouterReferer;
      if (profile.openRouterTitle) additional['X-Title'] = profile.openRouterTitle;
    }
    if (providerId === 'copilot') {
      additional['Copilot-Integration-Id'] = 'vscode-chat';
      additional['Editor-Version'] = 'vscode/1.99.0';
    }
    const data = await nativeStreamRequest(
      profile.endpoint,
      { method: 'POST', headers: buildBearerHeaders(profile, additional), body: JSON.stringify(body) },
      profile.timeoutSeconds,
      PROVIDER_DEFS[providerId]?.label || providerId,
      requestGuard,
      providerId === 'opencode_go',
      'openai_chat',
    );
    const text = extractOpenAIChatText(data);
    if (!text.trim()) throw new Error(`${providerId} returned empty content`);
    return text;
  }

  async function runOpenAIResponsesProvider(messages, profile, providerId, requestGuard = null) {
    if (!profile.endpoint) throw new Error(`${providerId} endpoint is empty`);
    if (!profile.model) throw new Error(`${providerId} model is empty`);
    let body = {
      model: profile.model,
      input: messages,
      max_output_tokens: profile.maxTokens,
      stream: true,
    };
    const temperature = optionalNumber(profile.temperature);
    if (temperature !== null) body.temperature = temperature;
    if (profile.reasoningEffort) body.reasoning = { effort: profile.reasoningEffort };
    if (profile.serviceTier) body.service_tier = profile.serviceTier;
    body = applyExtraBody(profile, body);
    if (messages.webSearch === true && providerSearchTool(providerId, profile)?.kind === 'openai_responses') body.tools = [...(Array.isArray(body.tools) ? body.tools : []), { type: 'web_search' }]; // 웹 검색(2026-10-15)
    const data = await nativeStreamRequest(
      profile.endpoint,
      { method: 'POST', headers: buildBearerHeaders(profile, openCodeGoHeaders(providerId)), body: JSON.stringify(body) },
      profile.timeoutSeconds,
      PROVIDER_DEFS[providerId]?.label || providerId,
      requestGuard,
      providerId === 'opencode_go',
      'openai_responses',
    );
    const text = extractOpenAIResponsesText(data);
    if (!text.trim()) throw new Error(`${providerId} returned empty content`);
    return text;
  }

  async function runClaudeProvider(messages, profile, requestGuard = null, providerId = 'claude') {
    if (!profile.endpoint) throw new Error('Claude endpoint is empty');
    if (!profile.model) throw new Error('Claude model is empty');
    const label = providerId === 'opencode_go' ? PROVIDER_DEFS.opencode_go.label : 'Claude';
    const systemParts = messages.filter((message) => message.role === 'system').map((message) => message.content);
    const chatMessages = messages.filter((message) => message.role !== 'system').map((message) => ({
      role: message.role === 'assistant' ? 'assistant' : 'user',
      content: String(message.content || ''),
    }));
    let body = {
      model: profile.model,
      max_tokens: profile.maxTokens,
      system: systemParts.join('\n\n'),
      messages: chatMessages,
      stream: true,
    };
    const temperature = optionalNumber(profile.temperature);
    if (temperature !== null) body.temperature = temperature;
    if (profile.claudeThinkingMode === 'adaptive') {
      body.thinking = { type: 'adaptive' };
      delete body.temperature;
    } else if (profile.claudeThinkingMode === 'enabled' && profile.thinkingTokens > 0) {
      body.thinking = { type: 'enabled', budget_tokens: profile.thinkingTokens };
      delete body.temperature;
    }
    if (profile.reasoningEffort) body.output_config = { effort: profile.reasoningEffort };
    body = applyExtraBody(profile, body);
    if (messages.webSearch === true && providerSearchTool(providerId, profile)?.kind === 'claude') body.tools = [...(Array.isArray(body.tools) ? body.tools : []), { type: 'web_search_20250305', name: 'web_search', max_uses: 3 }]; // 웹 검색(2026-10-15)
    const headers = {
      'Content-Type': 'application/json',
      'anthropic-version': '2023-06-01',
      ...openCodeGoHeaders(providerId),
      ...parseJsonRecord(profile.extraHeadersJson, {}),
    };
    // OpenCode Go reads the key of this format from x-api-key, as Anthropic does.
    if (profile.apiKey) headers['x-api-key'] = profile.apiKey;
    const data = await nativeStreamRequest(profile.endpoint, { method: 'POST', headers, body: JSON.stringify(body) }, profile.timeoutSeconds, label, requestGuard, providerId === 'opencode_go', 'claude');
    const text = extractClaudeText(data);
    if (!text.trim()) throw new Error(`${label} returned empty content`);
    return text;
  }

  function base64Url(input) {
    const bytes = input instanceof ArrayBuffer ? new Uint8Array(input) : new TextEncoder().encode(String(input));
    let binary = '';
    for (const byte of bytes) binary += String.fromCharCode(byte);
    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
  }

  function pemToArrayBuffer(pem) {
    const base64 = String(pem || '').replace(/-----[^-]+-----/g, '').replace(/\s+/g, '');
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return bytes.buffer;
  }

  async function getVertexAccessToken(profile, requestGuard = null) {
    requestGuard?.throwIfAborted('Vertex OAuth');
    if (vertexTokenCache && vertexTokenCache.expiresAt > Date.now() + 60000 && vertexTokenCache.key === fnv1a(profile.serviceAccountJson)) {
      return vertexTokenCache.token;
    }
    const timeoutSeconds = Math.max(0.001, Number(profile.timeoutSeconds || 0));
    const deadlineAt = Date.now() + (timeoutSeconds * 1000);
    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
    let requestAbort = null;
    const timeoutError = () => {
      const error = new Error(`Vertex OAuth timed out after ${profile.timeoutSeconds}s`);
      error.code = 'EROSYNC_PROVIDER_TIMEOUT';
      return error;
    };
    const abortOAuth = (reason = timeoutError()) => {
      try { controller?.abort(reason); } catch (_) { try { controller?.abort(); } catch (_) {} }
    };
    const waitWithinOAuthDeadline = async (promise, stage) => {
      Promise.resolve(promise).catch(() => {});
      requestGuard?.throwIfAborted(stage);
      const remainingMs = Math.max(0, deadlineAt - Date.now());
      if (remainingMs <= 0) {
        abortOAuth();
        throw timeoutError();
      }
      const guarded = requestGuard ? requestGuard.wait(Promise.resolve(promise), stage) : Promise.resolve(promise);
      try {
        return await withTimeout(guarded, remainingMs, 'Vertex OAuth deadline');
      } catch (error) {
        if (Date.now() >= deadlineAt || String(error?.message || '').includes('Vertex OAuth deadline timed out')) {
          abortOAuth();
          throw timeoutError();
        }
        throw error;
      }
    };
    if (controller && requestGuard?.signal) {
      requestAbort = () => abortOAuth(requestGuard.signal.reason);
      if (requestGuard.signal.aborted) requestAbort();
      else requestGuard.signal.addEventListener('abort', requestAbort, { once: true });
    }
    try {
      const serviceAccount = JSON.parse(profile.serviceAccountJson || '{}');
      if (!serviceAccount.client_email || !serviceAccount.private_key) throw new Error('Vertex service account JSON is incomplete');
      const now = Math.floor(Date.now() / 1000);
      const header = base64Url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
      const claim = base64Url(JSON.stringify({
        iss: serviceAccount.client_email,
        scope: 'https://www.googleapis.com/auth/cloud-platform',
        aud: serviceAccount.token_uri || 'https://oauth2.googleapis.com/token',
        iat: now,
        exp: now + 3600,
      }));
      const unsigned = `${header}.${claim}`;
      const key = await waitWithinOAuthDeadline(
        crypto.subtle.importKey('pkcs8', pemToArrayBuffer(serviceAccount.private_key), { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']),
        'Vertex OAuth key import',
      );
      const signature = await waitWithinOAuthDeadline(
        crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(unsigned)),
        'Vertex OAuth signing',
      );
      const assertion = `${unsigned}.${base64Url(signature)}`;
      const remainingSeconds = Math.max(0.001, (deadlineAt - Date.now()) / 1000);
      const data = await waitWithinOAuthDeadline(nativeJsonRequest(
        serviceAccount.token_uri || 'https://oauth2.googleapis.com/token',
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=${encodeURIComponent(assertion)}`,
          ...(controller?.signal ? { signal: controller.signal } : {}),
        },
        remainingSeconds,
        'Vertex OAuth',
        requestGuard,
      ), 'Vertex OAuth');
      if (!data?.access_token) throw new Error('Vertex OAuth response has no access_token');
      requestGuard?.throwIfAborted('Vertex OAuth');
      const tokenRecord = { token: data.access_token, expiresAt: Date.now() + (Number(data.expires_in || 3600) * 1000), key: fnv1a(profile.serviceAccountJson) };
      vertexTokenCache = tokenRecord;
      return tokenRecord.token;
    } finally {
      if (requestAbort && requestGuard?.signal) requestGuard.signal.removeEventListener('abort', requestAbort);
    }
  }

  // Adapted from the user-supplied text-to-pdf.ts (SHA-256 6E55654F).
  // Lazy scope: unavailable browser PDF primitives cannot break the default text path.
  async function createGeminiInputPdf(text) {
    const PAGE_WIDTH = 595.28;
    const PAGE_HEIGHT = 841.89;
    const DEFAULT_FONT_SIZE = 1;
    const DEFAULT_MARGIN = 0;
    const GLYPH_WIDTH = 0.5;
    const encoder = new TextEncoder();
    
    function bytes(value        )             {
        return encoder.encode(value);
    }
    
    function concat(chunks              )             {
        const length = chunks.reduce((total, chunk) => total + chunk.length, 0);
        const result = new Uint8Array(length);
        let offset = 0;
        for (const chunk of chunks) {
            result.set(chunk, offset);
            offset += chunk.length;
        }
        return result;
    }
    
    function pdfNumber(value        )         {
        return Number(value.toFixed(6)).toString();
    }
    
    function calculatePageGrid(fontSize        , margin        )                                    {
        if (!Number.isFinite(fontSize) || fontSize <= 0) {
            throw new RangeError("fontSize must be a positive finite number");
        }
        if (!Number.isFinite(margin) || margin < 0) {
            throw new RangeError("margin must be a non-negative finite number");
        }
    
        const columns = Math.floor((PAGE_WIDTH - margin * 2) / (fontSize * GLYPH_WIDTH));
        const rows = Math.floor((PAGE_HEIGHT - margin * 2) / fontSize);
        if (columns < 1 || rows < 1) {
            throw new RangeError("fontSize and margin leave no usable page area");
        }
        return { columns, rows };
    }
    
    function hex(value        )         {
        return value.toString(16).toUpperCase().padStart(4, "0");
    }
    
    function unicodeHex(value        )         {
        return [...value]
            .map((character) => {
                const codePoint = character.codePointAt(0) ;
                if (codePoint <= 0xff_ff) return hex(codePoint);
                const supplementary = codePoint - 0x1_00_00;
                return hex(0xd8_00 + (supplementary >> 10)) + hex(0xdc_00 + (supplementary & 0x03_ff));
            })
            .join("");
    }
    
    function wrapText(text        , columns        )             {
        const lines           = [];
        for (const hardLine of text.replaceAll(/\r\n?/g, "\n").split("\n")) {
            const characters = [...hardLine];
            if (characters.length === 0) {
                lines.push("");
                continue;
            }
            for (let index = 0; index < characters.length; index += columns) {
                lines.push(characters.slice(index, index + columns).join(""));
            }
        }
        return lines.map((line) => [...line]);
    }
    
    function isRtlCharacter(character        )          {
        const codePoint = character.codePointAt(0) ;
        return (
            (codePoint >= 0x05_90 && codePoint <= 0x08_ff) ||
            (codePoint >= 0xfb_1d && codePoint <= 0xfd_ff) ||
            (codePoint >= 0xfe_70 && codePoint <= 0xfe_ff) ||
            (codePoint >= 0x1_08_00 && codePoint <= 0x1_0f_ff) ||
            (codePoint >= 0x1_e8_00 && codePoint <= 0x1_ef_ff)
        );
    }
    
    // PDF text operators do not apply bidirectional layout. Reversing strong RTL runs for display lets
    // ToUnicode-aware extractors reconstruct their original logical order without embedding a font.
    function visualOrder(line          )           {
        const clusters             = [];
        for (const character of line) {
            if (/\p{Mark}/u.test(character) && clusters.length > 0) clusters.at(-1) .push(character);
            else clusters.push([character]);
        }
    
        const visual           = [];
        for (let index = 0; index < clusters.length;) {
            if (!isRtlCharacter(clusters[index][0])) {
                visual.push(...clusters[index]);
                index += 1;
                continue;
            }
            let end = index + 1;
            while (end < clusters.length && isRtlCharacter(clusters[end][0])) end += 1;
            for (let cursor = end - 1; cursor >= index; cursor--) visual.push(...clusters[cursor]);
            index = end;
        }
        return visual;
    }
    
    function createCharacterMap(lines            )                      {
        const characters = new Map                ();
        for (const line of lines) {
            for (const character of line) {
                if (characters.has(character)) continue;
                if (characters.size === 65_535) {
                    throw new RangeError("A PDF can contain at most 65,535 distinct characters");
                }
                characters.set(character, characters.size + 1);
            }
        }
        return characters;
    }
    
    function createToUnicodeCMap(characters                     )             {
        const entries = Array.from(characters, ([character, cid]) => `<${hex(cid)}><${unicodeHex(character)}>`);
        const mappings           = [];
        for (let index = 0; index < entries.length; index += 100) {
            const chunk = entries.slice(index, index + 100);
            mappings.push(`${chunk.length} beginbfchar\n${chunk.join("\n")}\nendbfchar`);
        }
    
        return bytes(
            [
                "/CIDInit /ProcSet findresource begin",
                "12 dict begin",
                "begincmap",
                "/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def",
                "/CMapName /PMUnicode-UCS def",
                "/CMapType 2 def",
                "1 begincodespacerange",
                "<0000><FFFF>",
                "endcodespacerange",
                ...mappings,
                "endcmap",
                "CMapName currentdict /CMap defineresource pop",
                "end",
                "end",
            ].join("\n"),
        );
    }
    
    function createPageContent(
        lines            ,
        characters                     ,
        fontSize        ,
        margin        ,
    )             {
        const commands = [
            "BT",
            `/F0 ${pdfNumber(fontSize)} Tf`,
            `${pdfNumber(fontSize)} TL`,
            `1 0 0 1 ${pdfNumber(margin)} ${pdfNumber(PAGE_HEIGHT - margin - fontSize)} Tm`,
        ];
        for (const [index, line] of lines.entries()) {
            const encoded = visualOrder(line)
                .map((character) => hex(characters.get(character) ))
                .join("");
            commands.push(`<${encoded}> Tj`);
            if (index < lines.length - 1) commands.push("T*");
        }
        commands.push("ET");
        return bytes(commands.join("\n"));
    }
    
    async function streamObject(data            )                      {
        const compressed = new Uint8Array(
            await new Response(
                new Blob([data            ]).stream().pipeThrough(new CompressionStream("deflate")),
            ).arrayBuffer(),
        );
        return concat([
            bytes(`<< /Length ${compressed.length} /Filter /FlateDecode >>\nstream\n`),
            compressed,
            bytes("\nendstream"),
        ]);
    }
    
    function serialize(objects              )             {
        const chunks = [concat([bytes("%PDF-1.7\n%"), new Uint8Array([255, 255, 255, 255]), bytes("\n")])];
        const offsets = [0];
        let length = chunks[0].length;
    
        for (const [index, object] of objects.entries()) {
            offsets.push(length);
            const serialized = concat([bytes(`${index + 1} 0 obj\n`), object, bytes("\nendobj\n")]);
            chunks.push(serialized);
            length += serialized.length;
        }
    
        const xrefOffset = length;
        const xref = [
            `xref\n0 ${objects.length + 1}`,
            "0000000000 65535 f ",
            ...offsets.slice(1).map((offset) => `${offset.toString().padStart(10, "0")} 00000 n `),
            "trailer",
            `<< /Size ${objects.length + 1} /Root 1 0 R >>`,
            "startxref",
            String(xrefOffset),
            "%%EOF",
        ].join("\n");
        chunks.push(bytes(`${xref}\n`));
        return concat(chunks);
    }
    
    async function textToPdf(text        , options                   = {})                {
        const fontSize = options.fontSize ?? DEFAULT_FONT_SIZE;
        const margin = options.margin ?? DEFAULT_MARGIN;
        const { columns, rows } = calculatePageGrid(fontSize, margin);
    
        const lines = wrapText(text, columns);
        const pages               = [];
        for (let index = 0; index < lines.length; index += rows) {
            pages.push(lines.slice(index, index + rows));
            if (pages.length > 1000) throw new RangeError("PDF page limit exceeded");
        }
        const characters = createCharacterMap(lines);
    
        const firstPageObject = 7;
        const pageIds = pages.map((_, index) => firstPageObject + index * 2);
        const objects               = [
            bytes("<< /Type /Catalog /Pages 2 0 R >>"),
            bytes(
                `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pages.length} /MediaBox [0 0 ${PAGE_WIDTH} ${PAGE_HEIGHT}] /Resources << /Font << /F0 3 0 R >> >> >>`,
            ),
            bytes(
                "<< /Type /Font /Subtype /Type0 /BaseFont /PMUnicode /Encoding /Identity-H /DescendantFonts [4 0 R] /ToUnicode 6 0 R >>",
            ),
            bytes(
                "<< /Type /Font /Subtype /CIDFontType2 /BaseFont /PMUnicode /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor 5 0 R /DW 500 /CIDToGIDMap /Identity >>",
            ),
            bytes(
                "<< /Type /FontDescriptor /FontName /PMUnicode /Flags 4 /FontBBox [0 -200 1000 800] /ItalicAngle 0 /Ascent 800 /Descent -200 /CapHeight 700 /StemV 80 /MissingWidth 500 >>",
            ),
            await streamObject(createToUnicodeCMap(characters)),
        ];
    
        for (const [index, page] of pages.entries()) {
            const pageId = pageIds[index];
            const contentId = pageId + 1;
            objects.push(
                bytes(`<< /Type /Page /Parent 2 0 R /Contents ${contentId} 0 R >>`),
                await streamObject(createPageContent(page, characters, fontSize, margin)),
            );
        }
    
        const pdf = serialize(objects);
        return new Blob([pdf            ], { type: "application/pdf" });
    }
    return textToPdf(text);
  }

  // ---------- AI 연결(2026-10-15, Erosync.Feedback-1015.Work-Plan.md 3·6·7절): 웹 검색 · Gemini 4 · 모델 검색 ----------

  // 웹 검색: 표준 도구 한 줄로 되는 제공자만. OpenAI(Responses 형식) · Claude · Vertex AI Gemini · OpenRouter(모델 무관). 나머지는 길이 없어 줄을 보이지 않는다.
  // 인물 분석(처음·재검사)에만 붙이고, 턴마다 하는 장면 판단·긴급 판단·8축 한글 호출에는 붙이지 않는다(부르는 쪽이 webSearch 옵션을 주는 곳만).
  const WEB_SEARCH_NOTE = 'WEB SEARCH: use the search tool only to verify facts about the original work, its world, and its characters. Do not invent facts the search did not confirm.';
  function providerSearchTool(providerId, profile) {
    if (providerId === 'openai') return String(profile?.apiFormat || 'openai_responses') === 'openai_responses' ? { kind: 'openai_responses', tool: { type: 'web_search' } } : null;
    if (providerId === 'claude') return { kind: 'claude', tool: { type: 'web_search_20250305', name: 'web_search', max_uses: 3 } };
    if (providerId === 'vertex') return { kind: 'gemini', tool: { googleSearch: {} } };
    if (providerId === 'openrouter') return { kind: 'openrouter', tool: { id: 'web' } };
    return null;
  }
  // 그 역할의 제공자에 검색이 켜져 있고 도구가 있을 때만
  function webSearchAllowed(providerId, profile) {
    return profile?.webSearch === true && !!providerSearchTool(providerId, profile);
  }
  // 요청 표시: 메시지 배열에 보이지 않는 표지를 단다(직렬화·복사에는 안 들어간다). 제공자 호출부가 이 표지를 보고 도구를 붙인다.
  function webSearchMark(messages, on) {
    if (on) Object.defineProperty(messages, 'webSearch', { value: true, enumerable: false, configurable: true });
    return messages;
  }
  // "웹 검색 시험": 검색 도구를 붙인 짧은 호출 한 번. 줄이 꺼져 있어도 도구를 붙여 본다. 결과만 보인다.
  

  // Gemini 4(gemini-4-…): temperature는 무시되므로 보내지 않고, 생각 깊이는 thinkingLevel(0 → low · 8,192 이하 medium · 그 위 high),
  // maxOutputTokens는 생각과 답을 합친 한도라 32,768 아래면 올리고 65,536을 넘기지 않는다. 다른 Gemini는 지금 그대로.
  function geminiGeneration4(model) {
    return /(?:^|\/)gemini-4(?:[-.]|$)/i.test(String(model || '').trim());
  }
  function geminiThinkingLevel(thinkingTokens) {
    const tokens = Number(thinkingTokens) || 0;
    return tokens <= 0 ? 'low' : tokens <= 8192 ? 'medium' : 'high';
  }
  // 모델 ID 형식: 앞뒤 공백은 떼고, 그래도 공백·한글이 들어 있으면 주소에 넣을 수 없는 값이다(구글 앞단 400의 흔한 원인).
  

  function toGeminiRequest(messages, profile) {
    const system = messages.filter((message) => message.role === 'system').map((message) => message.content).join('\n\n');
    const contents = messages.filter((message) => message.role !== 'system').map((message) => ({
      role: message.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: String(message.content || '') }],
    }));
    const gen4 = geminiGeneration4(profile.model);
    const generationConfig = { maxOutputTokens: gen4 ? Math.min(65536, Math.max(32768, Number(profile.maxTokens) || 0)) : profile.maxTokens };
    const temperature = optionalNumber(profile.temperature);
    if (temperature !== null && !gen4) generationConfig.temperature = temperature;
    if (gen4) generationConfig.thinkingConfig = { thinkingLevel: geminiThinkingLevel(profile.thinkingTokens) };
    else if (profile.thinkingTokens > 0) generationConfig.thinkingConfig = { thinkingBudget: profile.thinkingTokens };
    return {
      ...(system ? { systemInstruction: { parts: [{ text: system }] } } : {}),
      contents,
      generationConfig,
      ...(messages.webSearch === true ? { tools: [{ googleSearch: {} }] } : {}), // 웹 검색(Vertex AI만 표지를 받는다)
    };
  }

  async function runJsonTask(systemPrompt, userPrompt, config, role, label, options = {}) {
    const requestGuard = options.requestGuard || null;
    const allowRepair = options.repair !== false;
    const executionRole = ['director', 'profile', 'behind'].includes(options.executionRole) ? options.executionRole : role;
    const assignment = resolveRoleProfile(config, role);
    const retryContext = { remaining: clampInt(assignment.profile.retryCount, 0, 0, 3), used: 0, attemptNumber: 0, onStatus: options.onRequestStatus };
    // 웹 검색(2026-10-15): 부르는 쪽이 허용한 호출(인물 분석)에서, 그 역할의 제공자에 검색이 켜져 있고 도구가 있을 때만. 지시문에 한 문장을 덧붙이고 요청에 표시한다.
    const search = options.webSearch === true && webSearchAllowed(assignment.providerId, assignment.profile);
    const system = search ? `${systemPrompt}\n\n${WEB_SEARCH_NOTE}` : systemPrompt;
    const messages = webSearchMark([{ role: 'system', content: system }, { role: 'user', content: userPrompt }], search);
    const firstText = await runProvider(messages, config, role, requestGuard, executionRole, retryContext);
    options.onResponseInfo?.({ resultChars: String(firstText || '').length });
    requestGuard?.throwIfAborted(label);
    try {
      const parsed = extractJsonObject(firstText);
      return ['profile', 'director'].includes(executionRole)
        ? correctFractionalConfidenceScale(parsed, { role, executionRole, label })
        : parsed;
    } catch (firstError) {
      if (!allowRepair) throw firstError;
      requestGuard?.throwIfAborted(label);
      debug(config, `${label} JSON repair`, firstError.message);
      const repairMessages = webSearchMark([
        { role: 'system', content: `${system}\n\nThe previous output was invalid. Return only one corrected JSON object matching the schema.` },
        { role: 'user', content: `${userPrompt}\n\nPREVIOUS INVALID OUTPUT:\n${truncate(firstText, 8000)}` },
      ], search);
      const repairedText = await runProvider(repairMessages, config, role, requestGuard, executionRole, retryContext);
      requestGuard?.throwIfAborted(label);
      const repaired = extractJsonObject(repairedText);
      return ['profile', 'director'].includes(executionRole)
        ? correctFractionalConfidenceScale(repaired, { role, executionRole, label })
        : repaired;
    }
  }

  

  // ---------- 모델 검색: 제공자 목록 API에서 받은 이름(이번 실행 동안 기억) + 고정 추천 목록을 입력 글자로 거른다 ----------
  // 설정 화면에서 사용자가 모델 칸을 열거나 "모델 목록"을 누를 때만 부른다. 판단·분석 경로에는 닿지 않는다.
  // 한글 별칭 표: 입력에 든 한글 낱말을 영어 이름 조각으로 바꾸어 비교한다(제미니 플래시 → gemini, flash).
  
  
  
  // 입력 글자 → 비교 함수. 별칭으로 바꾸지 못한 한글이 남으면 아무것도 맞지 않는다(dead).
  
  // 제공자별 목록 요청. 없으면 null(OpenCode Go·리스 보조 모델은 고정 목록). 주소는 엔드포인트에서 만든다(Vertex만 고정 주소).
  
  // 요청 전에 아는 이유(키 없음 등). 빈 문자열이면 보낼 수 있다.
  
   // providerId → { key, at, models, error, pending }
  
  
  
  // 목록 받기: 같은 요청(주소·키)이면 이번 실행 동안 다시 받지 않는다. force면 다시 받는다. 못 받으면 error에 이유 한 줄.
  
  // "모델 목록" 단추: 다시 받고 상태 줄에 결과 한 줄
  
  // 모델 칸 아래 제안 상자: 초점·입력 때 거른 이름을 보이고, 누르거나 Enter로 고른다. 목록은 처음 열 때 한 번 받는다.
  

  

  function supportsGeminiPdf(providerId, profile) {
    return !['risu', 'ollama_cloud', 'claude'].includes(providerId)
      && (providerId === 'vertex' || ['vertex', 'gemini'].includes(profile?.apiFormat))
      && /(?:^|\/)gemini(?:[-.]|$)/i.test(String(profile?.model || ''));
  }

  function pdfBytesBase64(bytes) {
    let binary = '';
    for (let offset = 0; offset < bytes.length; offset += 8192) {
      binary += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
    }
    return btoa(binary);
  }

  async function prepareGeminiRequest(messages, profile, requestGuard = null, observer = null) {
    const body = applyExtraBody(profile, toGeminiRequest(messages, profile));
    const finish = (mode, reason = '', details = {}) => {
      const status = { mode, reason, ...details };
      observer?.(status);
      if (reason && profile.pdfInput) setUiStatus(`PDF 미적용 · ${reason} · 기존 텍스트로 전송합니다.`, 'warn');
      return body;
    };
    if (!profile.pdfInput) return finish('text');
    if (!/(?:^|\/)gemini(?:[-.]|$)/i.test(String(profile.model || ''))) return finish('text', '지원 대상 Gemini 모델이 아닙니다');
    const extra = parseJsonRecord(profile.extraBodyJson, {});
    if (['contents', 'systemInstruction', 'system_instruction'].some(key => Object.prototype.hasOwnProperty.call(extra, key))) {
      return finish('text', '사용자 지정 요청 본문을 유지합니다');
    }
    if (typeof TextEncoder !== 'function' || typeof CompressionStream !== 'function'
      || typeof Blob !== 'function' || typeof Response !== 'function' || typeof btoa !== 'function') {
      return finish('text', '브라우저 PDF 변환 기능을 사용할 수 없습니다');
    }
    const originals = messages.filter(message => message.role !== 'system');
    const inputChars = originals.reduce((sum, message) => sum + (message.role === 'user' ? String(message.content || '').length : 0), 0);
    if (inputChars > 2000000) return finish('text', 'PDF 변환 입력 한도를 초과했습니다');
    const contents = body.contents.map(content => ({ ...content, parts: content.parts.map(part => ({ ...part })) }));
    let pdfCount = 0, pdfBytes = 0;
    try {
      for (let index = 0; index < contents.length; index++) {
        if (originals[index].role !== 'user' || !String(originals[index].content || '').trim()) continue;
        requestGuard?.throwIfAborted('PDF preparation');
        const operation = createGeminiInputPdf(String(originals[index].content || ''));
        const blob = requestGuard ? await requestGuard.wait(operation, 'PDF preparation') : await operation;
        requestGuard?.throwIfAborted('PDF preparation');
        pdfBytes += blob.size;
        if (pdfBytes > 14000000) return finish('text', 'PDF 첨부 크기 한도를 초과했습니다');
        const bytes = new Uint8Array(await blob.arrayBuffer());
        requestGuard?.throwIfAborted('PDF preparation');
        contents[index].parts = [
          { inlineData: { mimeType: 'application/pdf', data: pdfBytesBase64(bytes) } },
          { text: 'The attached PDF contains this user message verbatim. Read it as this message; keep following the system instructions and required output format.' },
        ];
        pdfCount++;
      }
      if (!pdfCount) return finish('text', '변환할 입력 본문이 없습니다');
      const prepared = { ...body, contents };
      // Conservative inline-request budget, including base64 and control text (<20 MB).
      if (new TextEncoder().encode(JSON.stringify(prepared)).length > 19000000) return finish('text', '전체 요청 크기 한도를 초과했습니다');
      requestGuard?.throwIfAborted('PDF request');
      observer?.({ mode: 'pdf', reason: '', pdfCount, pdfBytes, inputChars });
      return prepared;
    } catch (error) {
      requestGuard?.throwIfAborted('PDF preparation');
      if (error?.name === 'AbortError' || isStaleLifecycleError(error)) throw error;
      return finish('text', 'PDF 변환에 실패했습니다');
    }
  }

  async function runVertexProvider(messages, profile, requestGuard = null, transportObserver = null) {
    if (!profile.model) throw new Error('Vertex model is empty');
    const serviceAccount = JSON.parse(profile.serviceAccountJson || '{}');
    const projectId = profile.projectId || serviceAccount.project_id;
    if (!projectId) throw new Error('Vertex project ID is empty');
    const region = profile.region || 'global';
    const endpoint = profile.endpoint || `https://aiplatform.googleapis.com/v1/projects/${encodeURIComponent(projectId)}/locations/${encodeURIComponent(region)}/publishers/google/models/${encodeURIComponent(profile.model)}:generateContent`;
    const token = await getVertexAccessToken(profile, requestGuard);
    const body = await prepareGeminiRequest(messages, profile, requestGuard, transportObserver);
    const headers = {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      ...parseJsonRecord(profile.extraHeadersJson, {}),
    };
    const data = await nativeJsonRequest(endpoint, { method: 'POST', headers, body: JSON.stringify(body) }, profile.timeoutSeconds, 'Vertex AI', requestGuard);
    const text = extractGeminiText(data);
    if (!text.trim()) throw new Error('Vertex AI returned empty content');
    return text;
  }

  async function runGeminiCustomProvider(messages, profile, requestGuard = null, transportObserver = null) {
    if (!profile.endpoint) throw new Error('Custom Gemini endpoint is empty');
    const body = await prepareGeminiRequest(messages, profile, requestGuard, transportObserver);
    const headers = { 'Content-Type': 'application/json', ...parseJsonRecord(profile.extraHeadersJson, {}) };
    if (profile.apiKey) headers['x-goog-api-key'] = profile.apiKey;
    const data = await nativeJsonRequest(profile.endpoint, { method: 'POST', headers, body: JSON.stringify(body) }, profile.timeoutSeconds, 'Custom Gemini', requestGuard);
    const text = extractGeminiText(data);
    if (!text.trim()) throw new Error('Custom Gemini returned empty content');
    return text;
  }

  function resolveRoleProfile(config, role) {
    const overrideProvider = role === 'profile' ? config.profileProvider : role === 'behind' ? config.behindProvider : config.directorProvider;
    const providerId = overrideProvider && overrideProvider !== 'inherit' ? overrideProvider : config.provider;
    const base = mergeProviderProfile(providerId, config.providers[providerId]);
    const overrideModel = role === 'profile' ? config.profileModel : role === 'behind' ? config.behindModel : config.directorModel;
    if (overrideModel) base.model = overrideModel;
    return { providerId, profile: providerId === 'opencode_go' ? resolveOpenCodeGoProfile(base, config.providers[providerId]?.model) : base };
  }

  // OpenCode Go serves each model family in its own request format, at its own path under one base address.
  const OPENCODE_GO_PATHS = Object.freeze({ openai_chat: '/chat/completions', openai_responses: '/responses', claude: '/messages' });

  // OpenCode Go asks every client to name itself and to send a stable session ID, and refuses a console key
  // without one (HTTP 400 MissingSessionID). One ID per plugin load keeps its routing and prompt caching stable.
  const OPENCODE_GO_SESSION = `erosync-${Array.from(globalThis.crypto?.getRandomValues?.(new Uint8Array(12)) || Array.from({ length: 12 }, () => Math.floor(Math.random() * 256)), (byte) => byte.toString(16).padStart(2, '0')).join('')}`;

  function openCodeGoHeaders(providerId) {
    return providerId === 'opencode_go' ? { 'x-opencode-session': OPENCODE_GO_SESSION, 'User-Agent': `Erosync/${VERSION}` } : {};
  }

  // Model IDs are lower case; the OpenCode app writes them with an `opencode-go/` prefix.
  function openCodeGoModelId(value) {
    return String(value || '').trim().replace(/^opencode-go\//i, '').toLowerCase();
  }

  function openCodeGoModelFormat(model) {
    const id = openCodeGoModelId(model);
    if (/^(?:grok|gpt|muse-spark)/.test(id)) return 'openai_responses';
    if (/^(?:minimax|qwen)/.test(id)) return 'claude';
    return 'openai_chat';
  }

  // The format and address of the model actually requested. A format the user chose is for the provider's own
  // model; a role's own model of another family is sent in the format of its family. The endpoint may be the
  // base address or any of the paths, with a query kept as it is.
  function resolveOpenCodeGoProfile(profile, defaultModel = profile.model) {
    const model = openCodeGoModelId(profile.model);
    const apiFormat = OPENCODE_GO_PATHS[profile.apiFormat] && model === openCodeGoModelId(defaultModel) ? profile.apiFormat : openCodeGoModelFormat(model);
    const [, address = '', rest = ''] = /^([^?#]*)([\s\S]*)$/.exec(String(profile.endpoint || '').trim() || PROVIDER_DEFS.opencode_go.endpoint);
    const base = address.replace(/\/+$/, '').replace(/\/(?:chat\/completions|responses|messages)$/i, '');
    return { ...profile, model, apiFormat, endpoint: base + OPENCODE_GO_PATHS[apiFormat] + rest };
  }

  function providerTaskBudgetMs(config, role) {
    const assignment = resolveRoleProfile(config, role);
    const retries = clampInt(assignment.profile.retryCount, 0, 0, 3);
    return providerAttemptLimitMs(assignment) * (retries + 1) + retries * 2000;
  }

  function providerFailure(error) {
    if (error?.code && /^EROSYNC_|^DIRECTOR_/.test(error.code)) return error;
    const message = String(error?.message || error || '');
    const failure = new Error('AI provider request failed');
    failure.status = clampInt(error?.status || error?.statusCode, 0, 0, 599);
    failure.code = failure.status ? 'EROSYNC_PROVIDER_HTTP'
      : /empty content|empty JSON response|no (?:text|content)|returned empty/i.test(message) ? 'EROSYNC_PROVIDER_EMPTY'
      : /timed out|timeout|ETIMEDOUT/i.test(message) ? 'EROSYNC_PROVIDER_TIMEOUT'
      : error?.name === 'AbortError' ? 'EROSYNC_PROVIDER_CANCELLED'
      : /fetch failed|failed to fetch|network|ECONNRESET|ECONNREFUSED|ENOTFOUND|socket/i.test(message) ? 'EROSYNC_PROVIDER_NETWORK'
      : /model is empty|endpoint is empty|project ID is empty|service account|private.key|api.key|runLLMModel is unavailable|플러그인 제공 보조 모델|Unexpected token|JSON value must/i.test(message) ? 'EROSYNC_PROVIDER_CONFIG'
      : 'EROSYNC_PROVIDER_FAILED';
    return failure;
  }

  async function runProvider(messages, config, role, requestGuard = null, executionRole = role, retryContext = null, transportObserver = null) {
    const assignment = resolveRoleProfile(config, role);
    const maxRetries = clampInt(assignment.profile.retryCount, 0, 0, 3);
    const retry = retryContext || { remaining: maxRetries, used: 0, attemptNumber: 0 };
    // With retries disabled, keep each caller's existing timeout/cancellation
    // policy (notably profile requests with separate OAuth and generation work).
    if (maxRetries === 0) {
      retry.attemptNumber += 1;
      retry.onStatus?.({ phase: 'requesting', attemptNumber: retry.attemptNumber, maxRetries: 0, retriesUsed: 0, retryDelayMs: 0, errorCode: '', httpStatus: 0, errorSource: '' });
      try {
        const result = await runProviderOnce(messages, config, role, requestGuard, executionRole, transportObserver);
        retry.onStatus?.({ requestOutcome: 'received', responseChars: String(result || '').length });
        return result;
      } catch (error) {
        const failure = providerFailure(error);
        retry.onStatus?.({ requestOutcome: 'failed', errorCode: failure.code, httpStatus: failure.status || 0, errorSource: failure.source || '' });
        throw failure;
      }
    }
    const taskGuard = requestGuard || createRequestGuard(providerTaskBudgetMs(config, role), `${role} task`);
    const fence = captureBackgroundFence();
    try {
      for (;;) {
        assertBackgroundFence(fence, 'provider request');
        taskGuard.throwIfAborted('provider request');
        const attemptGuard = createRequestGuard(Math.min(providerAttemptLimitMs(assignment), taskGuard.remainingMs()), `${role} request`);
        const abort = () => attemptGuard.abort(taskGuard.signal?.reason || staleLifecycleError('provider request cancelled'));
        taskGuard.signal?.addEventListener('abort', abort, { once: true });
        retry.attemptNumber += 1;
        retry.onStatus?.({ phase: 'requesting', attemptNumber: retry.attemptNumber, maxRetries, retriesUsed: retry.used, retryDelayMs: 0, errorCode: '', httpStatus: 0, errorSource: '' });
        let failure;
        try {
          const result = await runProviderOnce(messages, config, role, attemptGuard, executionRole, transportObserver);
          taskGuard.throwIfAborted('provider result');
          assertBackgroundFence(fence, 'provider result');
          retry.onStatus?.({ requestOutcome: 'received', responseChars: String(result || '').length });
          return result;
        } catch (error) {
          taskGuard.throwIfAborted('provider task');
          assertBackgroundFence(fence, 'provider result');
          failure = providerFailure(error?.code === 'EROSYNC_MAIN_REQUEST_DEADLINE'
            ? Object.assign(new Error('AI request timed out'), { code: 'EROSYNC_PROVIDER_TIMEOUT' }) : error);
          retry.onStatus?.({ requestOutcome: 'failed', errorCode: failure.code, httpStatus: failure.status || 0, errorSource: failure.source || '' });
        } finally {
          taskGuard.signal?.removeEventListener('abort', abort);
          attemptGuard.dispose();
        }
        const transient = ['EROSYNC_PROVIDER_NETWORK', 'EROSYNC_PROVIDER_TIMEOUT'].includes(failure.code)
          || (failure.code === 'EROSYNC_PROVIDER_HTTP' && [408, 429, 500, 502, 503, 504].includes(failure.status));
        // Risu calls may keep running after our timeout: never overlap an orphan.
        if (!transient || retry.remaining <= 0 || (assignment.providerId === 'risu' && risuActiveCalls.size > 0)) throw failure;
        const delay = Math.min(2000, 500 * (retry.used + 1));
        if (taskGuard.remainingMs() <= delay) throw failure;
        retry.remaining -= 1; retry.used += 1;
        retry.onStatus?.({ phase: 'retry_wait', maxRetries, retriesUsed: retry.used, retryDelayMs: delay, errorCode: failure.code, httpStatus: failure.status || 0, errorSource: failure.source || '' });
        let timer;
        try { await taskGuard.wait(new Promise(resolve => { timer = setTimeout(resolve, delay); }), 'provider retry delay'); }
        finally { clearTimeout(timer); }
      }
    } finally {
      if (!requestGuard) taskGuard.dispose();
    }
  }

  async function runProviderOnce(messages, config, role, requestGuard = null, executionRole = role, transportObserver = null) {
    if (exportReadBarrier) await exportReadBarrier.promise;
    if (!transferReadOnly && !exportWaitInProgress) assertTransferAdmission();
    else if (unloaded || stateRecoveryFault) throw staleLifecycleError('read-only export provider admission');
    const { providerId, profile } = resolveRoleProfile(config, role);
    debug(config, `${role} provider request`, { provider: providerId, model: profile.model || '(configured auxiliary)', format: profile.apiFormat });
    requestGuard?.throwIfAborted(`${role} provider`);
    let providerPromise;
    // Dusk 연결: 호스트가 runAI를 주면 기본 제공자(risu)를 Dusk의 AI 호출 경로로 보낸다(Dusk 모델 설정을 따른다). 없으면 원래 경로.
    if (providerId === 'risu' && typeof host.runAI === 'function') providerPromise = Promise.resolve(host.runAI(messages, role, requestGuard?.signal)).then((text) => {
      const out = typeof text === 'string' ? text : String(text?.text ?? '');
      if (!out.trim()) throw new Error('Dusk 모델이 빈 응답을 돌려줬어요');
      return out;
    });
    else if (providerId === 'risu') providerPromise = runRisuProvider(messages, profile, config, requestGuard, executionRole);
    else if (providerId === 'ollama_cloud' || profile.apiFormat === 'ollama_chat') providerPromise = runOllamaCloudProvider(messages, profile, requestGuard);
    else if (providerId === 'claude' || profile.apiFormat === 'claude') providerPromise = runClaudeProvider(messages, profile, requestGuard, providerId);
    else if (providerId === 'vertex' || profile.apiFormat === 'vertex') providerPromise = runVertexProvider(messages, profile, requestGuard, transportObserver);
    else if (profile.apiFormat === 'gemini') providerPromise = runGeminiCustomProvider(messages, profile, requestGuard, transportObserver);
    else if (profile.apiFormat === 'openai_responses') providerPromise = runOpenAIResponsesProvider(messages, profile, providerId, requestGuard);
    else providerPromise = runOpenAIChatProvider(messages, profile, providerId, requestGuard);
    const result = requestGuard ? await requestGuard.wait(providerPromise, `${role} provider`) : await providerPromise;
    requestGuard?.throwIfAborted(`${role} provider`);
    return result;
  }

  function correctFractionalConfidenceScale(value, context = {}) {
    const entries = [];
    const visit = (node, path = '') => {
      if (Array.isArray(node)) {
        node.forEach((item, index) => visit(item, `${path}[${index}]`));
        return;
      }
      if (!isPlainObject(node)) return;
      for (const [key, item] of Object.entries(node)) {
        const itemPath = path ? `${path}.${key}` : key;
        if (key === 'confidence') {
          const numericValue = typeof item === 'number' ? item : typeof item === 'string' && item.trim() ? Number(item) : NaN;
          entries.push({ node, key, value: numericValue, path: itemPath });
        }
        visit(item, itemPath);
      }
    };
    visit(value);
    if (entries.length === 0 || !entries.every((entry) => Number.isFinite(entry.value) && entry.value >= 0 && entry.value <= 1) || !entries.some((entry) => entry.value > 0)) return value;
    for (const entry of entries) entry.node[entry.key] = Math.round(entry.value * 100);
    log('AI confidence scale corrected from 0-1 to 0-100', {
      role: context.executionRole || context.role || '',
      task: context.label || '',
      fields: entries.length,
      paths: entries.map((entry) => entry.path),
    });
    return value;
  }



