  // Dusk 집착 방지(Erosync 설정 화면). 꺼짐이 기본이다. 켜면 (1) 집착성 값을 상한으로 눌러 장면 판단에 넘기고 (2) 같은 대상으로 목표가 연속되면 쉬게 한다.
  let duskGuard = { on: false, obsessionCap: 60, sameTargetTurns: 3, restTurns: 4 };
  function normalizeDuskGuard(v) {
    const n = (x, d, lo, hi) => Math.round(clampNumber(x, d, lo, hi));
    return { on: v?.on === true, obsessionCap: n(v?.obsessionCap, 60, 0, 100), sameTargetTurns: n(v?.sameTargetTurns, 3, 1, 20), restTurns: n(v?.restTurns, 4, 1, 50) };
  }
  function duskGuardSet(v) { duskGuard = normalizeDuskGuard(v); duskReadCache = null; return { ...duskGuard }; }
  // 같은 행동 인물이 같은 대상으로 목표를 이어 갈 때 연속 턴 수를 세고, 넘으면 쉬는 턴 동안 목표를 멈춘다(상태: state.duskGuard)
  function applyDuskGuard(state, action, goal) {
    if (!duskGuard.on || !goal) return goal;
    const g = (state.duskGuard ??= { streak: {}, rest: {} });
    const turn = Number(state.turnIndex || 0), key = `${action.actor}>${action.target}`;
    if (Number(g.rest[key] || 0) > turn) return { ...goal, status: 'pause' };
    const prev = g.streak[action.actor];
    const n = prev && prev.target === action.target && prev.turn >= turn - 1 ? prev.n + (prev.turn === turn ? 0 : 1) : 1;
    g.streak[action.actor] = { target: action.target, turn, n };
    if (n > duskGuard.sameTargetTurns) { g.rest[key] = turn + duskGuard.restTurns; delete g.streak[action.actor]; return { ...goal, status: 'pause' }; }
    return goal;
  }

  function effectiveProfileForDirector(profile, state, actorId, targetId = '') {
    const base = profile?.baseProfile || normalizeEroticProfile({});
    const development = normalizeDevelopmentState(state?.development);
    const global = development.global?.[actorId] || {};
    const effective = safeClone(base);
    // 미분석(값 없음) 축에는 성격 변화 차이를 더해 값을 만들지 않는다.
    // 성적 축 넷(2026-10-23, Erosync.Sexual-Axes-Development.Work-Plan.md): 성적 관심도는 2단계가 늘 쓰므로 값이 항상 있고, 성적 즉흥도·허용도·관성은 채점된 뒤에만 듣는다.
    const traits = DEVELOPMENT_NUMERIC_TRAITS.filter(trait => Number.isFinite(developmentTraitValue(base, trait)));
    for (const trait of traits) {
      setDevelopmentTraitValue(effective, trait, Math.round(clampNumber(clampNumber(developmentTraitValue(base, trait), 50) + clampNumber(global.numericDeltas?.[trait], 0, -35, 35), 50)));
    }
    const relation = targetId ? development.relations?.[relationKey(actorId, targetId)] || {} : {};
    for (const trait of traits) {
      setDevelopmentTraitValue(effective, trait, Math.round(clampNumber(clampNumber(developmentTraitValue(effective, trait), 50) + clampNumber(relation.numericDeltas?.[trait], 0, -35, 35), 50)));
    }
    // 성적 동기 유형 변화(2026-10-23, Erosync.Motive-Change.Work-Plan.md): 이 채팅의 덮기가 있으면 동기를 덮는다. 사용자 수정은 그 위에서 이긴다.
    const motiveOverride = normalizeSexualMotive(global.motiveOverride);
    if (motiveOverride) effective.sexualMotive = motiveOverride;
    const overridden = applyProfileOverrides(effective, profile?.userOverrides);
    if (duskGuard.on && Number.isFinite(overridden.obsessiveness)) overridden.obsessiveness = Math.min(overridden.obsessiveness, duskGuard.obsessionCap);
    overridden.developmentPatterns = [...(global.patterns || []), ...(relation.patterns || [])]
      .slice(-12)
      .map((item) => ({ label: item.label, direction: item.direction, confidence: item.confidence }));
    return overridden;
  }

  // 장면 판단 입력의 내부 관계: 대상별 성격 변화 보정·패턴을 함께 싣는다. SFW에서는 성적 축의 보정 키를 뺀다(2026-10-23, 성적 값과 같은 규칙).
  function compactRelationsForDirector(relations, candidateIds, development = null, policy = null) {
    const allowed = new Set([...candidateIds, 'user']);
    const sfw = policy?.contentMode === 'sfw';
    const compactDeltas = (deltas) => {
      const source = isPlainObject(deltas) ? deltas : {};
      return sfw ? Object.fromEntries(Object.entries(source).filter(([trait]) => !SEX_AXIS_KEYS.includes(trait))) : source;
    };
    const result = {};
    for (const [key, value] of Object.entries(relations || {})) {
      if (!isPlainObject(value) || value.from === 'user') continue;
      if (!allowed.has(value.from) || !allowed.has(value.to)) continue;
      result[key] = {
        from: value.from,
        to: value.to,
        affection: Math.round(clampNumber(value.affection, 50)),
        eroticAttraction: Math.round(clampNumber(value.eroticAttraction, 50)),
        hatred: Math.round(clampNumber(value.hatred, 0)),
        notes: latestStringList(value.notes, 8, 300), // 기록의 연속성(2026-10-29): 최신 8개
        baseLabel: truncate(value.baseLabel, 220),
        lastUpdatedTurn: value.lastUpdatedTurn || 0,
        behaviorDevelopment: isPlainObject(development?.relations?.[key]) ? {
          numericDeltas: compactDeltas(development.relations[key].numericDeltas),
          patterns: (development.relations[key].patterns || []).slice(-10).map((item) => ({ label: item.label, direction: item.direction, confidence: item.confidence })),
        } : null,
      };
    }
    return result;
  }

  // 장면 판단에 보내는 1단계 답: 축마다 답 문장과 신뢰도만(근거 인용은 뺌). 수위가 "사용 안 함"이면 극단성 답도 뺀다.




  function compactProfileForDirector(profile, entity, state, policy = null, profileStore = null) {
    const base = profile?.baseProfile || normalizeEroticProfile({});
    const sfw = policy?.contentMode === 'sfw';
    const axisAnswers = directorAxisAnswers(base.axisAnswers, policy);
    const result = {
      id: entity.id,
      name: entity.name,
      aliases: entity.aliases || [],
      category: entity.category,
      description: entity.description || '',
      baseProfile: compactEroticProfileForDirector(base, policy),
      effectiveProfile: compactEroticProfileForDirector(effectiveProfileForDirector(profile, state, entity.id), policy),
      // 정의학 1단계 답(값과 함께 읽는다). 정의는 지시문에 한 번만 있고 인물마다 붙이지 않는다.
      ...(axisAnswers ? { axisAnswers } : {}),
      sessionOverlay: isPlainObject(state?.actorStates?.[entity.id]) ? state.actorStates[entity.id] : {},
      userOverrides: { ...(profile?.userOverrides || {}) },
    };
    delete result.userOverrides.positionPreferences;
    delete result.userOverrides.menstrualCycle;
    if (sfw) for (const field of ['sexualPreferences', 'eroticInterest', 'sexualHumor', 'seduction']) delete result.userOverrides[field];
    if (policy && policy.extremityCap === null) delete result.userOverrides.extremity;
    const cycleContext = configCache?.cycleGoalInfluence === false || cycleOff(configCache) ? null : cycleContextForActor(profile, state, policy);
    if (cycleContext) result.temporaryBodyContext = cycleContext;
    // 생리 2차: 상대 쪽(그가 아는 "임신이 될 수 있는 관계")
    const partnerRisks = configCache?.cycleGoalInfluence === false || cycleOff(configCache) ? null : cyclePartnerContext(profile, state, policy, profileStore);
    if (partnerRisks) result.knownPregnancyRisks = partnerRisks;
    const preferenceAction = sfw ? null : (state?.lastPlan?.actions || []).find(action => action.actor === entity.id && (['flirt', 'seduce'].includes(action.mode) || normalizeGoalType(action.goal?.type) === 'sexual_intercourse'))
      || Object.values(state?.goals || {}).filter(goal => goal.actor === entity.id && ['active', 'continue_later'].includes(goal.status) && normalizeGoalType(goal.type) === 'sexual_intercourse').map(goal => ({ goal }))[0];
    const preferenceContext = sfw ? '' : positionPreferencesForAction(profile, state, preferenceAction);
    if (preferenceContext) result.preferenceContext = preferenceContext;
    if (JSON.stringify(result.baseProfile) === JSON.stringify(result.effectiveProfile)) {
      delete result.baseProfile;
      result.baseProfileSameAsEffective = true;
    }
    return result;
  }

  function hydrateBaseRelations(state, profileStore, allowedIds = null) {
    if (!isPlainObject(state.relations)) state.relations = {};
    const allowed = allowedIds instanceof Set ? new Set([...allowedIds, 'user']) : null;
    const activeSourceBundleKey = String(state.scopeMeta?.sourceBundleKey || '');
    const activeVariantKey = String(state.variantKey || 'default');
    const activeBasePairs = new Set();
    for (const suppression of Object.values(profileStore.baseRelationSuppressions?.entries || {})) {
      if (suppression.sourceBundleKey !== activeSourceBundleKey || String(suppression.variantKey || 'default') !== activeVariantKey || suppression.sessionScopeKey !== state.scopeKey) continue;
      const key = relationKey(suppression.from, suppression.to);
      const current = state.relations[key];
      if (!suppression.relationSnapshot && suppression.sessionSnapshot && current && Number(current.lastUpdatedTurn || 0) <= 0 && durableValueHash(current) === durableValueHash(suppression.sessionSnapshot)) {
        recordCommitPrev('relations', key, current);
        delete state.relations[key];
      }
    }
    for (const relation of Object.values(profileStore.baseRelations || {})) {
      if (!isPlainObject(relation) || !relation.from || !relation.to || relation.from === 'user') continue;
      if (activeSourceBundleKey && relation.sourceBundleKey !== activeSourceBundleKey) continue;
      if (String(relation.variantKey || 'default') !== activeVariantKey) continue;
      if (isBaseRelationSuppressed(profileStore, relation.sourceBundleKey || activeSourceBundleKey, activeVariantKey, relation.from, relation.to)) continue;
      activeBasePairs.add(relationKey(relation.from, relation.to));
    }
    for (const [key, current] of Object.entries(state.relations)) {
      if (!isPlainObject(current) || hasSessionRelationChanges(current)) continue;
      const ownership = isPlainObject(current.baseOwnership) ? current.baseOwnership : null;
      const explicitCurrentOwnership = !!ownership
        && ownership.sourceBundleKey === activeSourceBundleKey
        && String(ownership.variantKey || 'default') === activeVariantKey;
      const legacyBaseOnly = !ownership && (!!current.baseLabel
        || !!current.baseSourceHash
        || !!current.baseSignalType
        || current.basePositiveInterestQualified !== undefined
        || current.baseConfidence !== undefined);
      if ((explicitCurrentOwnership || legacyBaseOnly) && !activeBasePairs.has(key)) {
        recordCommitPrev('relations', key, current);
        delete state.relations[key];
      }
    }
    for (const relation of Object.values(profileStore.baseRelations || {})) {
      if (!isPlainObject(relation) || !relation.from || !relation.to || relation.from === 'user') continue;
      if (activeSourceBundleKey && relation.sourceBundleKey !== activeSourceBundleKey) continue;
      if (String(relation.variantKey || 'default') !== String(state.variantKey || 'default')) continue;
      if (isBaseRelationSuppressed(profileStore, relation.sourceBundleKey || state.scopeMeta?.sourceBundleKey || '', state.variantKey || 'default', relation.from, relation.to)) continue;
      if (allowed && (!allowed.has(relation.from) || !allowed.has(relation.to))) continue;
      const key = relationKey(relation.from, relation.to);
      const baseOwnership = {
        schemaVersion: 1,
        sourceBundleKey: relation.sourceBundleKey || activeSourceBundleKey,
        variantKey: String(relation.variantKey || activeVariantKey),
        directionalKey: variantRelationKey(relation.variantKey || activeVariantKey, relation.from, relation.to),
      };
      const current = isPlainObject(state.relations[key]) ? state.relations[key] : null;
      const baseReportedValues = {
        affection: Math.round(clampNumber(relation.reportedValues?.affection ?? relation.affection, 50)),
        eroticAttraction: Math.round(clampNumber(relation.reportedValues?.eroticAttraction ?? relation.eroticAttraction, 50)),
        hatred: Math.round(clampNumber(relation.reportedValues?.hatred ?? relation.hatred, 0)),
      };
      recordCommitPrev('relations', key, current || undefined);
      if (!current) {
        state.relations[key] = {
          from: relation.from,
          to: relation.to,
          affection: Math.round(clampNumber(relation.affection, 50)),
          eroticAttraction: Math.round(clampNumber(relation.eroticAttraction, 50)),
          hatred: Math.round(clampNumber(relation.hatred, 0)),
          notes: normalizeStringList(relation.notes, 30, 500),
          baseLabel: relation.label || '',
          baseConfidence: relation.confidence || 0,
          baseSourceHash: relation.sourceHash || '',
          baseSignalType: relation.signalType || 'setting_relation',
          basePositiveInterestQualified: relation.positiveInterestQualified === true,
          baseReportedValues,
          baseOwnership,
          lastUpdatedTurn: 0,
        };
      } else {
        const previousOwnership = isPlainObject(current.baseOwnership) ? current.baseOwnership : null;
        const explicitBaseCopy = !!previousOwnership
          && previousOwnership.sourceBundleKey === baseOwnership.sourceBundleKey
          && String(previousOwnership.variantKey || 'default') === String(baseOwnership.variantKey || 'default');
        const legacyBaseMarker = !previousOwnership && (!!current.baseLabel
          || !!current.baseSourceHash
          || !!current.baseSignalType
          || current.basePositiveInterestQualified !== undefined
          || current.baseConfidence !== undefined);
        const rehydrateBaseCopy = !hasSessionRelationChanges(current) && (explicitBaseCopy || legacyBaseMarker);
        if (rehydrateBaseCopy) {
          current.affection = Math.round(clampNumber(relation.affection, 50));
          current.eroticAttraction = Math.round(clampNumber(relation.eroticAttraction, 50));
          current.hatred = Math.round(clampNumber(relation.hatred, 0));
          current.notes = normalizeStringList(relation.notes, 30, 500);
        } else {
          current.notes = latestStringList([...(current.notes || []), ...(relation.notes || [])], 30, 500); // 기록의 연속성(2026-10-29): 최신 30개
        }
        current.baseLabel = relation.label || current.baseLabel || '';
        current.baseConfidence = relation.confidence || current.baseConfidence || 0;
        current.baseSourceHash = relation.sourceHash || current.baseSourceHash || '';
        current.baseSignalType = relation.signalType || current.baseSignalType || 'setting_relation';
        current.basePositiveInterestQualified = relation.positiveInterestQualified === true;
        current.baseReportedValues = baseReportedValues;
        current.baseOwnership = baseOwnership;
      }
    }
  }

  function selectDirectorCandidates(profileStore, registry, state, conversation, sourceProfiles, limit = DEFAULT_SCENE_CANDIDATES, policy = null) {
    const identityContext = bindRuntimeIdentity(registry, profileStore, state);
    const context = conversation.map((message) => message.content).join('\n').toLowerCase();
    const scores = new Map();
    const addScore = (id, score) => {
      if (id === 'user' || !identityContext.allowed(id) || !isProfileDirectorEligible(profileStore.profiles[id])) return;
      scores.set(id, (scores.get(id) || 0) + score);
    };
    for (const profile of sourceProfiles) addScore(profile.id, 30);
    for (const id of state.scene.presentAtEnd || []) addScore(id, 80);
    for (const id of state.scene.nextCastForecast?.confirmed || []) addScore(id, 70);
    for (const id of state.scene.nextCastForecast?.likely || []) addScore(id, 45);
    // 이름 조각(2026-10-31, Erosync.Name-Parts.Work-Plan.md 2절 1항) + 같은 글자 같은 점수(2026-10-31, Erosync.Name-Collision.Work-Plan.md 2절 1항):
    // 전체 이름·별칭이 대화에 있으면 60. 그게 없고 이름 조각만 있으면, 그 조각이 다른 허용 인물의 전체 이름·별칭과 같은 글자(그 인물이 60을 받는 글자)면 60, 아니면 40.
    // 인물당 한 번. 점수를 더할 뿐 깎지 않는다.
    const entities = Object.values(registry.entities);
    const exactHits = new Set();
    for (const entity of entities) {
      if (!identityContext.allowed(entity.id)) continue;
      for (const name of entityNames(entity)) if (name && context.includes(name)) exactHits.add(name);
    }
    for (const entity of entities) {
      if (entityNames(entity).some((name) => name && context.includes(name))) { addScore(entity.id, 60); continue; }
      const parts = entityNameParts(entity).filter((part) => mentionedInContext(context, part));
      if (!parts.length) continue;
      addScore(entity.id, parts.some((part) => exactHits.has(part)) ? 60 : 40);
    }
    for (const goal of Object.values(state.goals || {})) {
      if (!['complete', 'abandon'].includes(goal.status)) {
        addScore(goal.actor, 45);
        if (goal.target !== 'user') addScore(goal.target, 35);
      }
    }
    if (scores.size === 0) {
      for (const profile of sourceProfiles.slice(0, 4)) addScore(profile.id, 10);
    }
    return [...scores.entries()]
      .sort((left, right) => right[1] - left[1])
      .slice(0, clampInt(limit, DEFAULT_SCENE_CANDIDATES, 1, MAX_SCENE_CANDIDATES))
      .map(([id]) => compactProfileForDirector(profileStore.profiles[id], registry.entities[id], state, policy, profileStore));
  }



  function compactRivalriesForDirector(rivalries, candidateIds) {
    const allowed = new Set([...candidateIds, 'user']);
    return Object.values(isPlainObject(rivalries) ? rivalries : {})
      .filter((value) => isPlainObject(value) && value.actor !== 'user' && allowed.has(value.actor) && allowed.has(value.rival) && allowed.has(value.focusTarget))
      .slice(0, 40)
      .map((value) => ({
        id: value.id,
        actor: value.actor,
        rival: value.rival,
        focusTarget: value.focusTarget,
        kind: 'romantic',
        intensity: Math.round(clampNumber(value.intensity, 0)),
        reason: truncate(value.reason, 300),
        confidence: Math.round(clampNumber(value.confidence, 40)),
      }));
  }

  function compactGoalsForDirector(goals, candidateIds) {
    const allowed = new Set([...candidateIds, 'user']);
    return Object.values(goals || {})
      .filter((goal) => isPlainObject(goal) && goal.actor !== 'user' && allowed.has(goal.actor) && allowed.has(goal.target) && !['complete', 'abandon'].includes(goal.status))
      .slice(0, 30)
      .map((goal) => ({
        goalId: goal.goalId,
        actor: goal.actor,
        target: goal.target,
        type: goal.type,
        ...(normalizeGoalType(goal.type) === 'sexual_intercourse' ? { desire: Math.round(clampNumber(goal.desire, 50)) } : {}),
        objective: goal.objective,
        currentApproach: goal.currentApproach,
        nextMove: goal.nextMove,
        priority: goal.priority,
        persistence: goal.persistence,
        status: goal.status,
        lastAttemptTurn: goal.lastAttemptTurn,
      }));
  }

  function normalizeForecast(raw, registry, state, profileStore = null, candidateIds = null) {
    if (profileStore) bindRuntimeIdentity(registry, profileStore, state, null, { candidateIds }); // 이름 조각(2026-10-31)
    const source = isPlainObject(raw) ? raw : {};
    const normalizeIds = (values) => normalizeStringList(values, 30, 160)
      .map((value) => resolveEntity(registry, value, state.scopeKey))
      .filter(id => id && !isNonActingMainProfile(profileStore?.profiles?.[id]));
    const confirmed = [...new Set(normalizeIds(source.confirmed))];
    const likely = [...new Set(normalizeIds(source.likely).filter((id) => !confirmed.includes(id)))];
    const excluded = [...new Set(normalizeIds(source.excluded))];
    const arrivalSupported = [...new Set(normalizeIds(source.arrivalSupported))];
    const remoteContact = [...new Set(normalizeIds(source.remoteContact))];
    const rememberedOnly = [...new Set(normalizeIds(source.rememberedOnly))];
    return {
      location: truncate(source.location || state.scene.location, 300),
      confirmed,
      likely,
      excluded,
      arrivalSupported,
      remoteContact,
      rememberedOnly,
    };
  }

  function normalizeGoalType(value) {
    const raw = String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
    if (['sexual_intercourse', 'intercourse', 'sex', 'sex_goal'].includes(raw)) return 'sexual_intercourse';
    return truncate(raw || 'erotic_goal', 120);
  }

  function goalTypeLabel(value) {
    const type = normalizeGoalType(value);
    if (type === 'sexual_intercourse') return '성관계 목표';
    if (type === 'retaliation') return '보복 목표';
    return String(value || '일반 목표');
  }

  

  

  

  

  

  



  

  function normalizeGoalPlan(value, actor, target, turnIndex) {
    if (!isPlainObject(value)) return null;
    const goalId = safeKeyPart(value.goalId || `${actor}_${target}_${value.type || 'goal'}`, `goal_${turnIndex}_${fnv1a(`${actor}:${target}`)}`);
    const status = ['start', 'active', 'continue_later', 'pause', 'change', 'complete', 'abandon'].includes(value.status)
      ? value.status
      : 'active';
    const type = normalizeGoalType(value.type);
    return {
      goalId,
      actor,
      target,
      type,
      ...(type === 'sexual_intercourse' ? { desire: Math.round(clampNumber(value.desire, 50)) } : {}),
      triggerEventId: truncate(value.triggerEventId, 160),
      objective: truncate(value.objective, 600),
      currentApproach: truncate(value.currentApproach, 600),
      nextMove: truncate(value.nextMove, 700),
      priority: Math.round(clampNumber(value.priority, 50)),
      persistence: Math.round(clampNumber(value.persistence, 50)),
      status,
      lastAttemptTurn: turnIndex,
      ...(normalizeKocoRefs(value.kocoRefs).length ? { kocoRefs: normalizeKocoRefs(value.kocoRefs) } : {}),
    };
  }



  function deterministicRoll(turnKey, action) {
    return Number.parseInt(fnv1a(`${turnKey}:${action.actor}:${action.target}:${action.mode}`), 16) % 100;
  }

