  function entityDisplayName(registry, id) {
    if (id === 'user') return 'user';
    return registry.entities?.[id]?.name || id || '—';
  }

  // 설명은 기본으로 접어 두고, 이름 옆 작은 ?로 펼친다(UI 대개편: 화면에 긴 글을 늘어놓지 않음).
  

  

