  // 관계망 자료(지금 그래프가 쓰던 모델)를 '전체·전체 범위'로 한 번 만든다. 화면 상태 변수는 되돌린다.
  

  function uiPersonName(context, id) {
    if (id === 'user') return '당신';
    const registry = context.registry; return entityDisplayName(registry, id);
  }

  function uiProfileViewOf(profile, context, model = null) {
    const entity = context.registry.entities?.[profile.id] || {};
    const base = profile.baseProfile || normalizeEroticProfile({});
    const effective = effectiveProfileForDirector(profile, context.session, profile.id);
    const verdict = effectiveEntityVerdict(profile);
    const nonActing = isNonActingMainProfile(profile);
    const nonPerson = verdict.status === 'rejected_nonperson' || nonActing;
    const genderKey = profileGenderValue(profile); // 성별 수정값 우선(2026-10-23)
    const g = nonPerson || genderKey === 'genderless' ? 'x' : genderKey === 'female' ? 'f' : genderKey === 'male' ? 'm' : 'u';
    const category = entityCategoryLabel(entity, profile);
    const mob = category.includes('모브');
    const sourceIds = new Set(profile.sourceDocumentIds || []);
    const moduleNames = [...new Set((context.bundle?.sourceDocuments || []).filter((document) => sourceIds.has(document.id) && document.moduleName).map((document) => document.moduleName))];
    const module = category === '모듈' || moduleNames.length > 0;
    const sfw = contentPolicyFor(context.botOverride).contentMode === 'sfw';
    const level = Number(effective.eroticInterest?.level ?? base.eroticInterest?.level);
    const interest = nonPerson || sfw || !Number.isFinite(level) ? null : clampInt(level, 50, 0, 100);
    // 성적 축 셋·성적 동기(2026-10-22): 비인물·SFW면 null(가림). 미분석 값은 null.
    const sexualValue = axis => { const value = sexAxisValueOf(effective, axis) ?? sexAxisValueOf(base, axis); return Number.isFinite(value) ? clampInt(value, 50, 0, 100) : null; };
    const sexual = nonPerson || sfw ? null : { eroticInterest: interest, sexualSpontaneity: sexualValue('sexualSpontaneity'), sexualOpenness: sexualValue('sexualOpenness'), sexualMomentum: sexualValue('sexualMomentum') };
    const motive = nonPerson || sfw ? null : isPlainObject(effective.sexualMotive) ? effective.sexualMotive : isPlainObject(base.sexualMotive) ? base.sexualMotive : null;
    const preference = normalizeTargetGenderPreference(effective.targetGenderPreference || base.targetGenderPreference, normalizeGenderIdentity(profile.userOverrides?.genderIdentity || base.genderIdentity));
    const total = preference.malePercent + preference.femalePercent + preference.genderlessPercent;
    const pref = nonPerson || total <= 0 ? null : { f: preference.femalePercent, m: preference.malePercent, x: preference.genderlessPercent, total };
    const confidence = normalizeProfileConfidence(profile.profileConfidence || profile.confidence, profile.confidence ?? 50).overall;
    const axes = AXIS_KEYS.map(axis => {
      const baseValue = Number.isFinite(axisValueOf(base, axis)) ? axisValueOf(base, axis) : null;
      const effectiveValue = Number.isFinite(axisValueOf(effective, axis)) ? axisValueOf(effective, axis) : null;
      return { axis, base: baseValue, value: effectiveValue ?? baseValue };
    });
    let relationCount = 0, rivalries = 0;
    if (model) {
      const partners = new Set();
      for (const edge of model.allEdges) {
        if (edge.source === profile.id || edge.target === profile.id) partners.add(edge.source === profile.id ? edge.target : edge.source);
        if (edge.kind === 'rivalry' && edge.source === profile.id) rivalries += 1;
      }
      relationCount = partners.size;
    }
    const roleLabel = profile.isMain ? '메인' : mob ? '모브' : '주요';
    return { profile, profileId: profile.id, name: profile.name || profile.id, aliases: profile.aliases || [], entity, base, effective, verdict, nonActing, nonPerson, g, category, roleLabel, mob, module, moduleNames, sfw, interest, sexual, motive, preference, pref, confidence, axes, relationCount, rivalries };
  }

  

  

  

  

  

  

  
  

  

  
  

  

  

  

  

  

  

  

