  async function deleteBehindEntry(context, id = '') {
    assertTransferAdmission();
    if (!context.scope?.scopeKey) return;
    bumpBehindGeneration('chat', context.scope.sourceBundleKey || '', context.scope.scopeKey);
    const fence = captureBehindFence(context.scope);
    await enqueueBehindWrite(context.scope, async () => {
      assertBehindFence(fence, 'Behind delete start');
      const store = await loadBehindScenes(context.scope, { strict: true });
      assertBehindFence(fence, 'Behind delete read');
      store.entries = id ? store.entries.filter((entry) => entry.id !== id) : [];
      store.updatedAt = new Date().toISOString();
      assertBehindFence(fence, 'Behind delete write');
      await pluginStorageSet(behindStorageKey(context.scope), store);
      assertBehindFence(fence, 'Behind delete completion');
    });
    setUiStatus(id ? '비하인드 기록을 삭제했습니다.' : '현재 채팅의 비하인드 기록을 모두 삭제했습니다.', 'ok');
    await renderSettingsApp(false);
  }

