  function assertTransferAdmission() {
    if (transferBusy || exportWaitInProgress || unloaded || stateRecoveryFault) throw staleLifecycleError('backup/import admission');
  }

  async function yieldBackupControl() {
    const generation = transferGeneration, lifecycle = lifecycleEpoch;
    if (Date.now() - transferLastYieldAt >= 12) {
      await new Promise((resolve) => setTimeout(resolve, 0));
      transferLastYieldAt = Date.now();
    }
    if (unloaded || generation !== transferGeneration || lifecycle !== lifecycleEpoch || (transferBusy && transferCancelRequested)) throw staleLifecycleError('backup cooperative yield');
  }

  function trackTransferWrite(promise, tracked) {
    const pending = Promise.resolve(promise);
    tracked.add(pending);
    pending.then(() => tracked.delete(pending), () => tracked.delete(pending));
    return pending;
  }

  async function transferBounded(promise, timeoutMs = 10000) {
    let timer;
    try {
      return await Promise.race([promise, new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error('BACKUP_DRAIN_TIMEOUT')), timeoutMs);
      })]);
    } finally { clearTimeout(timer); }
  }

  async function drainTransferWriters() {
    const deadline = Date.now() + 10000;
    // Re-snapshot chained queues after each settlement: a profile commit can enqueue
    // manifest/audit work before it resolves. No new UI or model admission is allowed.
    for (;;) {
      const shared = sharedProfileRegistryWriteQueue, catalog = scopeCatalogWriteQueue;
      const audit = profileAuditWriteQueue, manifest = storageManifestWriteQueue;
      const writers = [shared, catalog, audit, manifest, ...scopeSessionWriteQueues.values(), ...behindWriteQueues.values(), ...transferStorageWrites, ...transferLocalWrites, ...preparedInvalidationJobs];
      await transferBounded(Promise.allSettled(writers), Math.max(1, deadline - Date.now()));
      await Promise.resolve();
      if (shared === sharedProfileRegistryWriteQueue && catalog === scopeCatalogWriteQueue && audit === profileAuditWriteQueue && manifest === storageManifestWriteQueue
        && !scopeSessionWriteQueues.size && !behindWriteQueues.size && !transferStorageWrites.size && !transferLocalWrites.size) return;
      if (Date.now() >= deadline) throw new Error('BACKUP_DRAIN_TIMEOUT');
    }
  }

  async function readOnlyBackupOperation(operation) {
    exportWaitInProgress = true;
    const fence = captureBackgroundFence();
    try {
      setUiStatus('장면 판단과 저장이 끝나면 백업을 내보냅니다. 진행 중인 판단은 취소하지 않습니다.', 'info');
      // Allow an already-committing output to register its director job first.
      await drainTransferWriters();
      const cohort = [...decisionPromises.values()];
      await transferBounded(Promise.allSettled(cohort), providerTaskBudgetMs(configCache || DEFAULT_CONFIG, 'director') + 10000);
      assertBackgroundFence(fence, 'backup export wait');
      if ([...decisionPromises.values()].some(job => !cohort.includes(job))) throw new Error('BACKUP_SCENE_CHANGED');
      transferBusy = true;
      transferReadOnly = true;
      transferPhase = 'draining';
      uiRenderGeneration += 1;
      if (uiRefreshTimer) clearTimeout(uiRefreshTimer);
      uiRefreshTimer = null;
      await drainTransferWriters();
      assertBackgroundFence(fence, 'backup export snapshot');
      if (decisionPromises.size > 0) throw new Error('BACKUP_SCENE_CHANGED');
      // No write is in flight here. Later background writes wait, instead of
      // throwing midway through a transaction or invalidating prepared goals.
      let release;
      exportReadBarrier = { promise: new Promise(resolve => { release = resolve; }), release: () => release() };
      transferStorageCapability = Object.freeze({});
      transferPhase = 'backup-export';
      return await operation();
    } finally {
      transferStorageCapability = null;
      transferBusy = false;
      transferReadOnly = false;
      transferPhase = 'idle';
      exportWaitInProgress = false;
      const barrier = exportReadBarrier; exportReadBarrier = null;
      barrier?.release();
    }
  }

  async function exclusiveBackupOperation(label, operation) {
    if (transferBusy || exportWaitInProgress || unloaded) throw new Error('BACKUP_BUSY');
    if (stateRecoveryFault && label !== 'backup-recovery') throw new Error('BACKUP_RECOVERY_REQUIRED');
    if (label === 'backup-export') return await readOnlyBackupOperation(operation);
    transferBusy = true;
    transferCancelRequested = false;
    transferPhase = 'draining';
    uiRenderGeneration += 1;
    if (uiRefreshTimer) clearTimeout(uiRefreshTimer);
    uiRefreshTimer = null;
    try {
      transferPriorMeta = await readBackupLocal(RESTORE_META_KEY, { schemaVersion: 1, manualHoldPartitions: [] });
      // Automatic refresh owns a selective rollback. Let it settle with its original
      // fence before invalidating all other tasks and before taking the storage lock.
      if (activeAutoProfileRefresh) {
        await transferBounded(preemptAutoProfileRefreshForMutation(activeAutoProfileRefresh.scope?.sourceBundleKey || '', 'backup/import requested'));
      }
      cancelDirectorAttempts('BACKUP_IMPORT_CANCELLED');
      await transferBounded(Promise.allSettled([...directorAttemptWrites.values()].map(entry => entry.promise)));
      transferGeneration += 1; lifecycleEpoch += 1; profileAuditGeneration += 1;
      bumpBehindGeneration('all');
      if (analysisRuntime.running) {
        analysisRuntime.cancelRequested = true; analysisRuntime.running = false;
        analysisRuntime.phase = 'cancelled'; analysisRuntime.detail = '백업·복원을 위해 진행 중인 분석을 중지했습니다.';
        analysisRuntime.finishedAt = Date.now();
      }
      preemptAllActiveRisuCalls('backup/import requested');
      for (const guard of transferRequestGuards) guard.abort(staleLifecycleError('backup/import request fence'));
      invalidateAllPreparedDecisionState('backup/import requested');
      pendingByCoordinates.clear(); pendingMainOrder.length = 0;
      await drainTransferWriters();
      if (unloaded) throw staleLifecycleError('backup drain');
      transferStorageCapability = Object.freeze({});
      transferPhase = label;
      return await operation();
    } finally {
      transferCancelConfirmation = null;
      transferStorageCapability = null;
      transferBusy = false;
      transferCancelRequested = false;
      transferPhase = 'idle';
    }
  }

  async function durableBackupLocalStore() {
    // A memory fallback cannot preserve a recovery snapshot across reload.
    if (typeof R.getLocalPluginStorage !== 'function') throw new Error('BACKUP_DURABLE_LOCAL_REQUIRED');
    return await getLocalStorage();
  }

  async function readBackupLocal(key, fallback = null) {
    const store = await durableBackupLocalStore();
    const read = requireReadableStorageState(key, await readStorageState(store, key));
    return read.status === 'missing' ? fallback : read.value;
  }

  async function writeBackupLocal(key, value) {
    if (unloaded) throw staleLifecycleError('local backup recovery write');
    const store = await durableBackupLocalStore();
    await trackTransferWrite(store.setItem(key, value), transferLocalWrites);
  }

  async function readRawBackupRecords(requestedKeys = null) {
    const records = new Map();
    const checked = new Set();
    const readKeys = async (keys) => {
      for (const key of [...new Set(keys)].sort()) {
        backupCodec.familyForKey(key);
        if (checked.has(key)) continue;
        checked.add(key);
        const read = await strictDurableRead(key);
        if (read.status === 'ok') records.set(key, read.value);
      }
    };
    if (requestedKeys) {
      await readKeys(requestedKeys);
    } else {
      await readKeys([PROFILE_STORE_KEY, REGISTRY_STORE_KEY, SCOPE_CATALOG_KEY, BOT_OVERRIDE_STORE_KEY, PROFILE_AUDIT_KEY, STORAGE_MANIFEST_KEY, LEGACY_PROFILE_STORE_KEY, PROFILE_PRESET_KEY]);
      const manifest = records.get(STORAGE_MANIFEST_KEY) || {}, catalog = records.get(SCOPE_CATALOG_KEY) || {};
      const profiles = records.get(PROFILE_STORE_KEY) || {}, registry = records.get(REGISTRY_STORE_KEY) || {};
      const scopes = new Map();
      const addScope = (scopeKey, variants = []) => {
        if (!scopeKey) return;
        backupCodec.familyForKey(`${SESSION_KEY_PREFIX}${scopeKey}`);
        const known = scopes.get(scopeKey) || new Set(['default']);
        for (const variant of variants.filter(Boolean)) {
          backupCodec.familyForKey(`${BEHIND_KEY_PREFIX}${scopeKey}:${variant}`);
          known.add(variant);
        }
        scopes.set(scopeKey, known);
      };
      for (const [scopeKey, entry] of Object.entries(manifest.sessions || {})) addScope(entry.scopeKey || scopeKey, [...(entry.variantKeys || []), entry.currentVariantKey]);
      for (const bot of Object.values(catalog.bots || {})) for (const [scopeKey, entry] of Object.entries(bot.chats || {})) addScope(entry.scopeKey || scopeKey, [entry.variantKey]);
      for (const profile of Object.values(profiles.profiles || {})) addScope(profile.scopeOwnership?.scopeKey, Object.keys(profile.variants || {}));
      for (const entity of Object.values(registry.entities || {})) addScope(entity.scopeKey, Object.keys(profiles.profiles?.[entity.profileId || entity.id]?.variants || {}));
      if (transferScope) addScope(transferScope.scopeKey, [transferScope.variantKey]);
      for (const [key, entry] of Object.entries(manifest.behind || {})) { backupCodec.familyForKey(key); addScope(entry.scopeKey, [entry.variantKey]); }
      await readKeys([...scopes.keys()].flatMap((scopeKey) => [`${SESSION_KEY_PREFIX}${scopeKey}`, `${LEGACY_SESSION_PREFIX}${scopeKey}`]));
      for (const scopeKey of scopes.keys()) {
        const session = records.get(`${SESSION_KEY_PREFIX}${scopeKey}`);
        if (session) addScope(scopeKey, [session.variantKey, ...Object.keys(session.variantStates || {})]);
        const botKey = scopeKey.split(':')[0];
        addScope(scopeKey, Object.keys(profiles.sourceBundles?.[botKey]?.variants || {}));
      }
      await readKeys([
        ...Object.keys(manifest.behind || {}), ...(manifest.auxiliaryKeys || []),
        ...[...scopes].flatMap(([scopeKey, variants]) => [...variants].map((variant) => `${BEHIND_KEY_PREFIX}${scopeKey}:${variant}`)),
      ]);
    }
    return [...records].sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0).map(([key, value]) => ({ key, value }));
  }

  async function invalidateBackupCaches() {
    observeCompatibility('clear');
    if (compatibilityUiTimer) clearTimeout(compatibilityUiTimer);
    compatibilityUiTimer = null;
    sourceTransportBindings.clear();
    sessionIdentityRepairChecked.clear();
    kocoPacketCache.clear(); clearKocoScanCache(); uiPanelViews.clear(); uiLastContext = null;
    invalidateSharedStateCaches();
    configCache = null; configStorageFault = null; botOverrideCache = null; storageManifestCache = null;
    vertexTokenCache = null; uiDraftReset(null);
    profileCompilePromises.clear(); verificationPromises.clear(); decisionPromises.clear(); decisionCache.clear();
    resyncPromises.clear(); behindPromises.clear(); profileRefreshStates.clear();
    resetScopedUiSelection();
    invalidateAllPreparedDecisionState('backup data restored');
    const recovery = await readBackupLocal(RESTORE_RECOVERY_KEY);
    if (recovery?.phase === 'complete') {
      const metadata = recovery.transferMetadata;
      if (!metadata || !['scoped-chat', 'full-backup'].includes(metadata.kind) || !Array.isArray(metadata.affectedPartitions)) throw new Error('BACKUP_SCOPE_METADATA_REQUIRED');
      const previous = metadata.beforeMeta || transferPriorMeta || { schemaVersion: 1, manualHoldPartitions: [] };
      const partitions = metadata.kind === 'scoped-chat' ? [...(previous.manualHoldPartitions || []), ...metadata.affectedPartitions] : metadata.affectedPartitions;
      transferMeta = { schemaVersion: 1, manualHoldPartitions: [...new Set(partitions)].sort(), recoveryHash: await backupCodec.sha256(recovery) };
      await writeBackupLocal(RESTORE_META_KEY, transferMeta);
      if (backupCodec.canonicalStringify(await readBackupLocal(RESTORE_META_KEY)) !== backupCodec.canonicalStringify(transferMeta)) throw new Error('BACKUP_META_READBACK');
    } else if (recovery?.phase === 'rolled_back' && (recovery.transferMetadata?.beforeMeta || transferPriorMeta)) {
      transferMeta = recovery.transferMetadata?.beforeMeta || transferPriorMeta;
      await writeBackupLocal(RESTORE_META_KEY, transferMeta);
      if (backupCodec.canonicalStringify(await readBackupLocal(RESTORE_META_KEY)) !== backupCodec.canonicalStringify(transferMeta)) throw new Error('BACKUP_META_READBACK');
    }
    stateRecoveryFault = null;
  }

  function getBackupService() {
    if (backupService) return backupService;
    const coordinator = createErosyncBackupService({
      codec: backupCodec, scopeTools: backupScopeTools,
      io: {
        exclusive: exclusiveBackupOperation,
        yieldControl: yieldBackupControl,
        assertCurrent: () => {
          if (unloaded || !transferBusy || !transferStorageCapability || transferCancelRequested) throw staleLifecycleError('backup operation ownership');
        },
        describeImport: (envelope) => {
          const rows = envelope.sections.flatMap((section) => section.records);
          const profiles = rows.find(({ key }) => key === PROFILE_STORE_KEY)?.value;
          const kind = envelope.kind, scope = envelope.scope;
          const affectedPartitions = kind === 'scoped-chat' ? [`${scope.sourceBundleKey}::${scope.variantKey}`]
            : Object.entries(profiles?.sourceBundles || {}).flatMap(([botKey, bundle]) => [...new Set([bundle.activeVariantKey || 'default', ...Object.keys(bundle.variants || {})])].map((variant) => `${botKey}::${variant}`));
          const chatKeys = new Set(rows.filter(({ key }) => key.startsWith(SESSION_KEY_PREFIX)).map(({ key }) => key.slice(SESSION_KEY_PREFIX.length)));
          const dataCounts = { bots: Object.keys(profiles?.sourceBundles || {}).length, chats: chatKeys.size, variants: affectedPartitions.length, profiles: Object.keys(profiles?.profiles || {}).length };
          return { kind, scope: safeClone(scope), affectedPartitions, dataCounts };
        },
        readRecords: readRawBackupRecords,
        transaction: async (label, writes) => {
          const capability = transferStorageCapability;
          if (!capability) throw new Error('BACKUP_LOCK_REQUIRED');
          return await commitStateTransactionWithinLock(label, writes, { capability, compactProgress: true, fence: captureBackgroundFence() });
        },
        readConfig: async () => {
          const stored = await readBackupLocal(LOCAL_CONFIG_KEY);
          if (!isPlainObject(stored)) throw new Error('BACKUP_CONFIG_REQUIRED');
          return stored;
        },
        writeConfig: async (value) => await writeBackupLocal(LOCAL_CONFIG_KEY, value),
        readRecovery: async () => {
          const stored = await readBackupLocal(RESTORE_RECOVERY_KEY);
          if (!stored) return stored;
          const { transferMetadata, ...marker } = stored;
          return marker;
        },
        writeRecovery: async (value) => {
          const stored = await readBackupLocal(RESTORE_RECOVERY_KEY);
          const metadata = value.phase === 'prepared' && transferActiveImportMetadata
            ? { ...transferActiveImportMetadata, beforeMeta: safeClone(transferPriorMeta) }
            : stored?.transferMetadata;
          await writeBackupLocal(RESTORE_RECOVERY_KEY, { ...value, ...(metadata ? { transferMetadata: metadata } : {}) });
        },
        invalidateCaches: invalidateBackupCaches,
        markRecoveryRequired: async () => { requireStateRecovery(new Error('BACKUP_RECOVERY_FAILED')); },
      },
    });
    backupService = Object.freeze({
      exportBackup: coordinator.exportBackup,
      recoverPending: coordinator.recoverPending,
      prepareImport: async (text, kind, scope = null) => {
        const prepared = await coordinator.prepareImport(text, kind, scope);
        transferPreparedMetadata.set(prepared, safeClone(prepared.metadata));
        return prepared;
      },
      prepareImportWithReader: async (readText, kind, scope = null) => {
        const prepared = await coordinator.prepareImportWithReader(readText, kind, scope);
        transferPreparedMetadata.set(prepared, safeClone(prepared.metadata));
        return prepared;
      },
      restore: async (prepared, options = {}) => {
        if (transferBusy || unloaded) throw new Error('BACKUP_BUSY');
        const metadata = transferPreparedMetadata.get(prepared);
        if (!metadata) throw new Error('BACKUP_PREPARED_INVALID');
        transferActiveImportMetadata = metadata;
        try {
          return await coordinator.restore(prepared, { ...options, confirm: async (preview) => await options.confirm({ ...preview, dataCounts: metadata.dataCounts }) });
        } finally { transferActiveImportMetadata = null; }
      },
    });
    return backupService;
  }

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  

  // 화면용 보관 판정: 현재 변형에서 허용되지 않은 인물이 걸린 기록인가
  

  

  

  

  





  
  



  
  
  




  function uiJournalChangePreview(state, messages, scopeKey = '') {
    if (!state?.commitJournal?.length || !Array.isArray(messages)) return null;
    const commits = readChatCommits(messages, scopeKey, firstJournalMessageIndex(state?.commitJournal));
    if (!commits) return null;
    const byId = new Map(commits.filter(row => row.id).map(row => [row.id, row]));
    let previous = -1, edited = false;
    for (const entry of state.commitJournal) {
      const found = entry.messageId ? byId.get(entry.messageId) : commits.find(row => row.index === entry.messageIndex);
      if (!found || found.index <= previous) return { reason: 'rollback', removedTurnKeys: [], removedCommitIds: [] };
      const matches = journalEntryMatchesChat({ ...entry }, [found], previous);
      if (entry.unverified === true || !matches || found.index !== entry.messageIndex) {
        if (!matches && !isEditedCommitCandidate(entry, found)) return { reason: 'rollback', removedTurnKeys: [], removedCommitIds: [] };
        edited = true;
      }
      previous = found.index;
    }
    return edited ? { reason: 'postprocess', removedTurnKeys: [], removedCommitIds: [] } : null;
  }

  

  

  

  

  

